'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='word-choice')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('reader','From read + agent suffix -er; read is an Old English verb. Reader names someone who reads books, articles, or other written material.',[C('reader.s1','教育','The reader finished two essays on the train ride home.','这位读者在回家途中读完了两篇文章。','a reader of + text','名词，指阅读书籍、文章等的人。','person reads written material.','教育'),C('reader.s1','教育','The reader marked unfamiliar phrases as she worked through the article.','这位读者阅读文章时标记了不熟悉的短语。','reader + of + text','说明该人所阅读的内容。','person reads an article and marks unfamiliar phrases.','教育')],M('The reader finished the article without reading any of its words.','The reader finished the article after reading it carefully.','reader 指阅读者；完全没有阅读文字就“读完”相互矛盾。','meaning'),[Q(1,'A careful reader of a report is…','a person who reads and understands it','the report’s printer','a person who writes the report only','Reader sense 1 names someone who reads written material.','meaning'),Q(1,'What does a careful reader do while studying an article?','follows and understands its written content','measures the paper’s weight','records a radio signal','A reader is a person who reads written material.','context'),Q(1,'Which phrase is natural?','a reader of novels','a reader to three liters','reader the book up','Reader of + text identifies what someone reads.','grammar'),Q(1,'Which word is the agent noun related to read?','reader','readily','readingly','The suffix -er forms a person who performs the action of reading.','word-formation')]);
P('readership','From reader + -ship; reader derives from read. Readership means the collective audience or number of regular readers of a publication or author.',C('readership.s1','媒体','The magazine expanded its readership by publishing a free online edition.','这本杂志通过推出免费网络版扩大了读者群。','a publication’s readership; expand readership','集合名词，指经常阅读某刊物或作者的群体，也可指其人数。','online edition attracts more readers.','媒体'),M('The newspaper’s readership grew although no one read or received it.','The newspaper’s readership grew as more people began reading it.','readership 是实际读者群或读者人数；无人阅读就不会扩大。','meaning'),[Q(1,'A newspaper’s readership is…','the group or number of people who read it regularly','the reporters who write its articles','the cost of printing each issue','Readership refers to the publication’s audience.','meaning'),Q(1,'How might a journal increase its readership?','make articles easier for more readers to access','remove every article from circulation','stop publishing new issues','Readership grows when more people can and do read the journal.','context'),Q(1,'Which phrase is common?','a large readership','a readership of temperature','readership the station quickly','Readership can be described as large or small.','collocation'),Q(1,'What does “the author has an international readership” mean?','readers in many countries follow the author’s work','the author writes only about international law','the author is a newspaper printer','The word names the author’s collective audience.','meaning')]);
P('readily','From ready + -ly; ready comes from Old English ræde “prepared.” Readily can mean willingly, easily, or quickly without hesitation.',[C('readily.s1','通用','She readily agreed to help organize the neighborhood clean-up.','她欣然同意帮忙组织社区清洁活动。','readily agree/accept/help','表示自愿、乐意而非被迫。','agreement is willing.','通用'),C('readily.s2','通用','The stain came off readily with warm water.','用温水很容易就把污渍洗掉了。','readily available/understood/removed','表示不费力或没有困难。','stain is easily removed.','通用'),C('readily.s3','通用','He readily answered when the interviewer asked his name.','采访者问到姓名时，他立刻作了回答。','readily respond/answer','表示迅速而毫不迟疑地作出反应。','response is immediate.','通用')],M('She readily refused the invitation because she was forced to accept it against her will.','She reluctantly accepted the invitation because she was forced to do so.','readily 表示乐意；被迫且违心接受应使用 reluctantly。','distinction'),[Q(1,'A person who readily volunteers…','offers willingly','is forced to volunteer','has no time to respond','Readily in sense 1 means willingly.','meaning'),Q(2,'If a label is readily legible, it is…','easy to read','impossible to find','written by a reader','Sense 2 means without difficulty.','meaning'),Q(3,'She readily replied to the alarm. She replied…','quickly and without hesitation','after several weeks','unwillingly and under pressure','Readily can describe a prompt response.','meaning'),Q(1,'Which sentence uses readily to mean willingly?','He readily shared his notes with the class.','The lock readily opened with one turn.','She readily answered the phone at once.','Sharing notes is a voluntary act; the other examples emphasize ease or speed.','distinction')]);
P('reading','From read + -ing; read comes from Old English rǣdan “advise, interpret, read.” Reading is the activity of understanding written words or a text assigned to be read.',C('reading.s1','教育','Daily reading helped the child recognize unfamiliar words.','每天阅读帮助孩子识别不熟悉的词。','reading practice/material','名词，指阅读行为或供阅读的文本。','practice improves literacy.','教育'),M('Her reading improved after she stopped looking at written words entirely.','Her reading improved after she practiced understanding written words each day.','阅读能力不能通过完全不接触文字而提高。','meaning'),[Q(1,'Reading in “daily reading improves vocabulary” means…','the activity of understanding written text','a number displayed by a thermometer','a district ruled by a queen','The source sense is the act of reading.','meaning'),Q(1,'A teacher assigns a reading for Monday. The student should…','read the selected text','repair the classroom','calculate a quart','A reading can be a text chosen for study.','context'),Q(1,'Which phrase is natural?','reading comprehension','reading to a quart','readings a reader','Reading commonly combines with comprehension, practice, or material.','collocation'),Q(1,'Which sentence uses reading as a learning activity?','The course includes an hour of reading each day.','The meter reading was 68 degrees.','Her reading of the poem was one interpretation.','The first sentence describes the activity; the others involve a measurement or interpretation outside this source entry’s primary sense.','distinction')]);
P('readjust','From re- + adjust; adjust comes from French ajuster, ultimately Latin ad- + justus “right.” Readjust means adjust again or adapt to changed conditions.',C('readjust.s1','通用','After the move, the family readjusted its weekly routine to fit the longer commute.','搬家后，这家人重新调整每周作息，以适应更长的通勤时间。','readjust a plan/setting; readjust to + change','可及物表示再次调整，也可指适应新的生活条件。','routine changes to fit new situation.','通用'),M('They readjusted the chair by leaving it exactly where it was and changing nothing.','They readjusted the chair by raising its seat to a more comfortable height.','readjust 要再次改变设置或位置；完全不作调整与之相反。','meaning'),[Q(1,'To readjust a schedule after a delay is to…','change it again to fit the new situation','follow it without any change','read it aloud to a group','Readjust means adjust again.','meaning'),Q(1,'After moving to a new country, someone may readjust to…','different routines and surroundings','an unchanged old address','a four-sided shape','Readjust to means adapt to changed circumstances.','context'),Q(1,'Which pattern is correct?','readjust the settings','readjust to the settings it again','readjusting the settings yesterdayly','Readjust is transitive when an object is changed.','grammar'),Q(1,'The prefix re- in readjust means…','again','before','without','Re- indicates that the adjustment is made another time.','word-formation')]);
P('ready','From Old English ræde “prepared, ready,” related to riding/being prepared; as adjective ready means prepared, willing/about to act, or immediately available; verb ready means prepare.',[C('ready.s1','通用','The rescue team was ready before the storm reached the coast.','风暴抵达海岸前，救援队已经准备就绪。','ready for + event; ready to do','形容准备好应对或完成某事。','team is prepared in advance.','通用'),C('ready.s2','通用','I am ready to leave as soon as the taxi arrives.','出租车一到，我就愿意马上出发。','be ready to do; ready for action','表示愿意或即将做某事。','speaker is willing and about to leave.','通用'),C('ready.s3','通用','Keep a first-aid kit ready in the kitchen.','在厨房备好一个急救包。','keep something ready','表示物品现成、可立即使用。','kit is available when needed.','通用'),C('ready.s4','书面','The crew readied the boat before sunrise.','船员在日出前把船准备妥当。','ready/readied someone or something','动词：为即将发生的事情做好准备。','crew prepares the boat.','通用')],M('The emergency kit was ready because every item was missing and unavailable.','The emergency kit was not ready because its supplies were missing.','物品缺失且无法使用说明尚未准备好。','meaning'),[Q(1,'A team ready for a storm is…','prepared for it','unaware that it may happen','the storm itself','Ready sense 1 means prepared.','meaning'),Q(2,'“I am ready to leave” means…','I am willing or about to leave','I refuse to leave under any circumstances','I have already arrived home','Ready to do can express willingness or imminence.','meaning'),Q(3,'A ready supply of batteries is…','available for immediate use','waiting to be manufactured next year','a supply of reading assignments','Ready can mean at hand and usable now.','context'),Q(4,'In “The staff readied the room,” readied means…','prepared it','read it aloud','made it less available','Ready as a verb means make prepared.','grammar')]);
P('reagent','From re- + agent, coined in French/German scientific vocabulary; a reagent is a substance used to detect, analyze, or participate in a chemical reaction.',[C('reagent.s1','通用','The technician added a reagent that changed color in the presence of copper.','技术员加入了一种遇铜会变色的试剂。','a reagent for testing + substance','试剂用于测试样本中是否存在某物。','color change indicates copper.','化学'),C('reagent.s2','通用','In the reaction, sodium was a reagent that combined with chlorine.','在这项反应中，钠是一种与氯结合的反应物。','a reagent in a reaction','反应物义强调该物质参与化学变化。','sodium participates in reaction.','化学')],M('The reagent merely observed the reaction from outside and did not test or react with anything.','The reagent was added to test for copper and took part in the chemical reaction.','reagent 是用于检测或参与反应的物质，而非旁观者。','meaning'),[Q(1,'A chemical reagent is used to…','test for or detect another substance','measure how many readers a paper has','put a meeting off','A reagent is a substance used in chemical testing.','meaning'),Q(2,'If sodium combines with chlorine, sodium acts as…','a reagent in the reaction','a newspaper readership','a court receiver','A reagent may participate in a chemical change.','context'),Q(1,'Which phrase is natural?','add a reagent to the sample','add a reagent of a queen','reagent the sample away','A reagent is added to a sample to test its contents or initiate a reaction.','collocation'),Q(1,'Which is a plausible sign that a reagent detected copper?','the sample changes color','the room becomes a realm','the sample forms a queue','A color change can be an indicator reaction.','context')]);
P('real','From Old French reel, from Latin realis “actual,” from res “thing”; real can mean existing, genuine, serious/emphatic, or informally “very.”',[C('real.s1','通用','The museum confirmed that the signature was real, not forged.','博物馆确认这个签名是真迹，并非伪造。','real vs. imagined','指实际存在、不是想象出来的。','signature exists authentically.','通用'),C('real.s2','通用','The jeweler checked whether the pearl was real or imitation.','珠宝商检查这颗珍珠是真品还是仿制品。','real/genuine + object','表示真正的、非仿制品或伪装。','genuineness is assessed.','通用'),C('real.s3','口语','The hikers faced a real danger when the river rose.','河水上涨时，徒步者面临着十足的危险。','a real problem/danger','形容词用于强调问题或危险的严重程度。','danger is substantial.','口语'),C('real.s4','口语','That was real kind of you to carry the boxes upstairs.','你帮忙把箱子搬上楼，真是太好了。','real + adjective (informal)','非正式副词用法，相当于 very，尤其见于美式英语。','real intensifies kind.','口语')],M('The real diamond was an imaginary object that did not exist.','The real diamond was an actual stone, not an imaginary one.','实际存在的钻石与想象中的物体不能同时成立。','meaning'),[Q(1,'A real event is one that…','actually happened or exists','was imagined in a story only','is a receipt for payment','Real in sense 1 means actually existing.','meaning'),Q(2,'A real diamond is…','genuine rather than imitation','a picture of a diamond','a person who sells property','Real can mean genuine, not a copy.','meaning'),Q(3,'“That is a real danger” emphasizes that the danger is…','serious and substantial','imaginary','a quarter long','Real can intensify a noun phrase to mean actual or significant.','context'),Q(4,'In informal “real nice,” real means…','very','rarely','not genuinely','Informal real can function as an adverb meaning very.','grammar')]);
P('real estate','From real “relating to things/property,” via Anglo-French real estate; estate derives from Latin status “standing, condition.” The phrase means land and buildings as property.',C('real estate.s1','金融','They invested in real estate near the new railway station.','他们投资了新火车站附近的房地产。','buy/sell/invest in real estate','不可数名词，指土地及其上的建筑物等不动产。','investment consists of land/property.','金融'),M('The broker sold real estate by transferring ownership of a portable cup of coffee.','The broker sold real estate by transferring ownership of a house and its land.','房地产指土地和建筑物，不是可移动的咖啡杯。','meaning'),[Q(1,'Real estate includes…','land and buildings','only movable personal clothing','a publication’s readership','Real estate is property consisting of land and buildings.','meaning'),Q(1,'Which phrase is natural?','invest in real estate','invest real estate in a quart','real estate the question off','Invest in real estate is a common construction.','collocation'),Q(1,'A real-estate agent helps clients…','buy, sell, or rent property','prepare chemical reagents','recite a poem','The field concerns transactions involving land and buildings.','context'),Q(1,'Why is real estate usually uncountable?','It names property as a general category or market.','It always refers to exactly one house.','It is a plural form of realtor.','The phrase commonly treats property collectively rather than as countable units.','grammar')]);
P('realism','From French réalisme, from réel “real”; realism can mean lifelike representation in art, a practical attitude, or the philosophical belief that things exist independently.',[C('realism.s1','通用','The painter’s realism is visible in the careful detail of the workers’ hands.','从工人双手的细致刻画中，可以看出画家的现实主义风格。','literary/artistic realism','艺术义：力求如实呈现生活与现实。','details depict ordinary life closely.','艺术'),C('realism.s2','通用','Realism about the budget forced the team to reduce its plans.','对预算保持现实态度，迫使团队缩减计划。','political/practical realism','指务实地接受现实条件，而非抱不切实际的希望。','limits are acknowledged.','通用'),C('realism.s3','通用','Philosophical realism holds that the external world exists independently of our minds.','哲学实在论认为外部世界独立于我们的心灵而存在。','philosophical realism','哲学义：认为事物并不依赖人的意识而存在。','doctrine concerns independent existence.','哲学')],M('The artist’s realism made every scene look like an abstract dream with no recognizable details.','The artist’s surrealism made every scene look like an abstract dream.','完全抽象、梦幻且无写实细节与 realism（写实主义）相反。','distinction'),[Q(1,'A novel praised for realism…','portrays life in a lifelike way','uses only impossible fantasy','contains no recognizable people or settings','Artistic realism aims to represent life as it is.','meaning'),Q(2,'A politician showing realism about costs…','accepts practical limits','ignores every budget constraint','writes a philosophical proof','Sense 2 is a practical attitude toward facts and constraints.','context'),Q(3,'Philosophical realism asserts that the world…','exists independently of our minds','is created only by each person’s imagination','has no physical objects','Philosophical realism concerns the independent existence of things.','meaning'),Q(1,'Which phrase most clearly refers to an art movement?','nineteenth-century realism in painting','realism about a travel budget','realism in a philosophical argument','The first explicitly concerns representation in visual art.','distinction')]);
P('realist','From French réaliste, from réel “real”; a realist accepts facts, creates lifelike art, or supports philosophical realism.',[C('realist.s1','通用','A realist knows the team cannot finish the entire project in one afternoon.','现实主义者知道团队不可能一个下午完成整个项目。','a realist about + situation','指不抱不切实际希望、按现实看待事情的人。','speaker accepts practical limits.','通用'),C('realist.s2','通用','The realist novelist described factory work without romanticizing it.','这位现实主义小说家如实描写工厂劳动，没有加以浪漫化。','a realist writer/artist','指以写实方式表现生活的作家或艺术家。','work depicts ordinary life accurately.','艺术'),C('realist.s3','通用','The philosopher is a realist about the existence of the external world.','这位哲学家是外部世界实在论者。','a philosophical realist','哲学义：相信事物独立于意识而存在的人。','belief is independent reality.','哲学')],M('The realist expected the impossible deadline to be met effortlessly despite no staff or time.','The optimist expected the deadline to be met; the realist pointed out that more staff and time were needed.','忽视现实限制、认为不可能的截止时间轻松可达，不符合 realist 的务实态度。','meaning'),[Q(1,'A realist about a deadline…','considers the actual time and resources available','assumes every plan will succeed magically','writes only about imaginary worlds','Sense 1 describes someone who accepts facts and practical limits.','meaning'),Q(2,'A realist artist typically…','represents life in a detailed, lifelike way','avoids all recognizable subjects','paints only geometric symbols','Sense 2 names an artist or writer in the realist tradition.','context'),Q(3,'A philosophical realist believes that…','things exist independently of the mind','the outside world is only a dream','all objects are paintings','Philosophical realism asserts independent existence.','meaning'),Q(1,'Which adjective is most closely related to realist in the practical sense?','practical','imaginary','puritanical','A realist is practical in assessing actual circumstances.','distinction')]);
P('realistic','From real + -istic, via French réaliste; realistic means practical and fact-based, or accurately representing real life.',[C('realistic.s1','通用','The manager set a realistic goal that the team could reach in six weeks.','经理设定了一个团队能在六周内实现的现实目标。','realistic plan/expectation','务实义：符合实际条件、可实现。','deadline matches resources.','通用'),C('realistic.s2','艺术','The sculptor made a realistic portrait with natural skin texture.','雕塑家制作了一尊皮肤纹理自然、栩栩如生的肖像。','realistic image/portrait','艺术义：描绘得逼真、接近现实。','texture resembles real skin.','艺术')],M('Their realistic plan required one person to complete a year of work in an hour with no tools.','Their unrealistic plan required one person to complete a year of work in an hour with no tools.','目标极不可能，应用 unrealistic，而不是 realistic。','meaning'),[Q(1,'A realistic estimate is…','based on what is actually possible','deliberately impossible','a painting of a person','Realistic sense 1 means practical and consistent with facts.','meaning'),Q(2,'A realistic portrait looks…','lifelike','like an unrelated receipt','impossible to recognize by design','Artistic realistic means resembling real people or things.','context'),Q(1,'Which noun commonly follows realistic?','expectation','quark','receptionist','A realistic expectation is a common phrase.','collocation'),Q(1,'Which contrasts with realistic in planning?','unrealistic','practical','achievable','Unrealistic describes a plan that does not fit actual possibilities.','distinction')]);
P('realistically','From realistic + -ally; realistic comes from real. Realistically means with practical regard for facts, or in a lifelike way.',C('realistically.s1','通用','Realistically, the repairs will take at least two weeks.','实事求是地说，维修至少需要两周。','realistically assess/expect','副词：按实际情况或可能性来判断。','speaker gives practical time estimate.','通用'),M('Realistically, the one-hour repair will require three months and cannot be finished before tomorrow.','Realistically, the repair will take about one hour and should be finished today.','严重自相矛盾的时长不能称为实事求是的估计。','meaning'),[Q(1,'To assess a plan realistically is to…','consider practical facts and limits','ignore evidence and assume magic','paint the plan like a portrait','Realistically means in a way that accepts what is actually possible.','meaning'),Q(1,'Which sentence uses realistically correctly?','Realistically, we need another week to finish testing.','Realistically of the test was blue.','They realistically the week into a room.','The adverb can introduce a fact-based estimate.','grammar'),Q(1,'A filmmaker recreates a storm realistically. The storm looks…','lifelike','like a quarterly receipt','impossible to see','Realistically can describe an accurate, lifelike representation.','context'),Q(1,'Which adverb is closest in meaning to realistically in a planning discussion?','practically','imaginarily','recklessly','A practical assessment takes real constraints into account.','distinction')]);
P('reality','From Old French realite, from Latin realis “actual”; reality is the state or facts of things as they actually exist.',C('reality.s1','通用','The team had to face the reality that the bridge needed expensive repairs.','团队不得不面对桥梁需要昂贵维修这一现实。','face/accept the reality that + clause','名词，指实际情况或真实存在的状态。','costly repairs are an actual fact.','通用'),M('The reality was that the bridge had never been built, although thousands of cars crossed it every day.','The reality was that the bridge had not been built, so no cars could cross it.','未建成的桥不可能每天承载车辆，句内事实互相冲突。','meaning'),[Q(1,'Reality is…','the state of things as they actually exist','a fictional character’s invented world only','an official receipt','Reality contrasts with imagination or appearance.','meaning'),Q(1,'“Face reality” means…','accept the actual facts','avoid learning anything','make a portrait look lifelike','The phrase means stop denying what is actually true.','collocation'),Q(1,'A family accepts the reality that their house needs a new roof. They accept…','an actual condition they must deal with','a rumor about a different house','the roof as a fictional character','Reality names the actual state of affairs.','context'),Q(1,'Which phrase is natural?','the reality of the situation','the reality at a quart to','reality the meeting off','Reality of the situation is a common construction.','grammar')]);
P('realization','From realize + -ation; realize comes through French réaliser from réel “real.” Realization means achieving a plan, suddenly understanding, or converting assets into money.',[C('realization.s1','通用','The realization of the housing plan took five years of steady work.','这项住房计划的实现历经五年持续努力。','realization of a goal/plan','名词：使计划、希望或承诺成为现实。','plan is achieved.','通用'),C('realization.s2','通用','Her realization that the keys were still inside came too late.','她意识到钥匙还在屋里时已经太晚了。','the realization that + clause','名词：突然明白某个事实。','new understanding arrives.','通用'),C('realization.s3','通用','The realization of the estate’s assets paid the outstanding debts.','变卖遗产资产所得款项偿还了未清债务。','realization of assets','商业义：出售财产并取得现金。','assets converted to money.','商业')],M('The realization of the project meant the plan remained only an unstarted idea.','The realization of the project meant the plan had been carried out.','实现计划表示已经落实，而非仍未开始。','meaning'),[Q(1,'The realization of a plan is…','the act of making it happen','a sudden feeling of nausea','a person who reads a publication','Realization sense 1 means achievement or fulfillment.','meaning'),Q(2,'Her realization that the gate was locked was…','her sudden understanding of that fact','the act of building the gate','a cash payment for the gate','Sense 2 is a moment of understanding.','meaning'),Q(3,'In financial language, realization of assets means…','selling property to obtain money','buying assets without paying','reading an asset’s description','Sense 3 means turning property or shares into cash.','context'),Q(1,'Which phrase naturally expresses sudden understanding?','a realization that the address was wrong','a realization of four quarts','realization for a realtor','Realization that + clause can introduce the newly understood fact.','grammar')]);
P('realize','From French réaliser, based on réel “real”; realize means become aware, make a plan real, or sell property to obtain cash.',[C('realize.s1','通用','I did not realize the last bus left at nine.','我没意识到末班车九点就开了。','realize that + clause','开始明白此前未注意到的事实。','speaker becomes aware of schedule.','通用'),C('realize.s2','书面','The charity realized its goal of building a village clinic.','慈善机构实现了建造乡村诊所的目标。','realize a goal/hope/plan','使目标、希望或计划成为现实。','goal is achieved.','通用'),C('realize.s3','商业','The owners realized a profit when they sold the building.','业主出售大楼时获得了利润。','realize a profit/assets','通过出售财产或投资获取现金或利润。','sale converts property into money.','商业')],M('She realized the goal of opening a clinic by abandoning the project before it began.','She failed to realize the goal of opening a clinic because she abandoned the project.','放弃项目并未实现建诊所的目标。','meaning'),[Q(1,'If you realize that you left your keys at home, you…','become aware of that fact','sell the keys for cash','make a new key into a house','Realize in sense 1 means come to understand or notice.','meaning'),Q(2,'To realize a dream is to…','make it come true','forget that it exists','sell it to an investor','Realize can mean achieve or fulfill an ambition.','meaning'),Q(3,'An investor realizes a profit by…','selling an asset for a gain','forgetting the purchase price','putting off a receipt','The business sense is convert assets into money, often at a profit.','context'),Q(1,'Which pattern is correct?','realize that the train is delayed','realize the train be delayed','realize to the train delayed','Realize can take a that-clause to state what someone understands.','grammar')]);
P('really','From real + -ly; real derives from Latin realis “actual.” Really means truly/in fact and can add emphasis to an adjective or statement.',C('really.s1','通用','The package really did arrive before noon, as the tracking record shows.','包裹确实在中午前送到了，物流记录可以证明这一点。','really do/think/mean','副词，强调事实或真实性。','tracking record supports assertion.','通用'),M('She was really asleep because she was fully awake and speaking to us.','She was really asleep because she did not wake when we called.','完全清醒并交谈与 asleep 相矛盾。','meaning'),[Q(1,'“I really saw the comet” emphasizes that…','the speaker truly saw it','the speaker only imagined it','the comet was a reader','Really can mean truly or in fact.','meaning'),Q(1,'In “That was really helpful,” really means…','very or especially','never','by accident','Really commonly intensifies an adjective.','grammar'),Q(1,'Which sentence uses really to correct a doubt?','She really sent the form yesterday; here is the receipt.','She really the receipt yesterdayly.','She sent a really yesterday.','The first stresses that the action did occur.','context'),Q(1,'Which is closest to really in “I really agree”?','truly','rarely','unwillingly','Really emphasizes sincerity or truth.','meaning')]);
P('realm','From Old French reaume, from Latin regimen “rule, government”; realm can mean an area of activity or a kingdom ruled by a monarch.',[C('realm.s1','书面','The debate belongs to the realm of public policy, not engineering.','这场辩论属于公共政策领域，而不是工程领域。','the realm of + subject/activity','引申指知识、兴趣或活动的范围。','topic is assigned to a field.','书面'),C('realm.s2','历史','The queen governed a realm that stretched across several islands.','女王统治着一个横跨数座岛屿的王国。','rule/govern a realm','历史义：君主统治的国家或领土。','monarch rules territory.','历史')],M('The realm of marine biology was a kingdom ruled by a queen on an island.','The realm of marine biology is a field of study; a queen ruled the island kingdom.','科学领域的 realm 与君主统治的领土义不应混为一个概念。','distinction'),[Q(1,'“The realm of physics” means…','the field or area of physics','a monarch’s crown','a real-estate office','Realm sense 1 means a domain of knowledge or activity.','meaning'),Q(2,'A queen rules a realm. Here realm is…','a country or territory under her rule','a scientific theory only','a kind of reading material','Sense 2 is a kingdom or domain ruled by a monarch.','context'),Q(1,'Which phrase is natural?','within the realm of possibility','within a realm of three quarts','realm the statement out','Realm of possibility is a common figurative phrase.','collocation'),Q(1,'Which sentence uses realm figuratively?','Tax law is outside my realm of expertise.','The queen expanded her realm.','The ruler inherited a realm.','The first means area of expertise rather than kingdom.','distinction')]);
P('realtime','From real + time; the technical adjective describes processing or response as events happen, without a stored delay.',C('realtime.s1','技术','The dashboard displays realtime traffic data from roadside sensors.','仪表盘实时显示来自路边传感器的交通数据。','realtime data/processing','技术形容词：数据到达时立即处理或显示。','sensor feed updates without delay.','技术'),M('The realtime display showed yesterday’s data only after a six-month delay.','The delayed report showed data six months later; the realtime display updates as events happen.','六个月延迟与 realtime（实时）相反。','distinction'),[Q(1,'Realtime data are processed…','as the events happen','only after being stored for months','once every quarter','Realtime means without a stored delay.','meaning'),Q(1,'Which phrase is natural?','realtime monitoring','realtime of a pyramid','monitoring realtimelyly','Realtime commonly modifies data, response, or monitoring.','collocation'),Q(1,'A realtime map updates as traffic changes. What is its key feature?','it reflects current events promptly','it displays only last year’s traffic','it is a paper map with no updates','Realtime systems respond as new information arrives.','context'),Q(1,'Which contrasts with realtime processing?','batch processing after a delay','immediate updates','live data display','Delayed batch processing is the opposite of realtime response.','distinction')]);
P('realtor','From real estate + agent suffix -or; the term denotes an agent who arranges property sales, especially in North America.',C('realtor.s1','商业','The realtor arranged a viewing of the apartment for Saturday morning.','房地产经纪人安排了周六上午看公寓。','a realtor helps buy/sell property','名词，指协助买卖土地或房屋的经纪代理人。','agent schedules property showing.','商业'),M('The realtor sold the apartment by prescribing medicine to the tenants.','The realtor sold the apartment by listing it and arranging viewings.','房地产经纪人从事物业交易，不是开药的医疗人员。','confusable'),[Q(1,'A realtor typically helps clients…','buy or sell property','analyze quarks','prepare a reading anthology','A realtor is a property sales agent.','meaning'),Q(1,'Which phrase is natural?','contact a realtor about buying a house','contact a realtor to quench the fire','realtor the property back','A realtor can advise or arrange a property transaction.','collocation'),Q(1,'A buyer asks a realtor to schedule a home viewing. The realtor will…','arrange a visit to see the property','approve a chemical reagent','change the buyer’s reading level','Realtors arrange showings as part of property transactions.','context'),Q(1,'Which field does a realtor work in?','real estate','recessive genetics','pyrotechnics','Realtors work with land and buildings.','meaning')]);
P('reap','From Old English rīpan “cut grain”; reap means harvest a crop or receive results produced by earlier actions.',[C('reap.s1','农业','Workers reap the barley in late summer and store it in dry barns.','工人们在夏末收割大麦，并将其存放在干燥的谷仓里。','reap a crop/harvest','及物动词：收割并收集成熟的谷物。','barley is harvested.','农业'),C('reap.s2','书面','Students who practice daily often reap the benefits later.','每天练习的学生往往会在以后收获益处。','reap the benefits/rewards/consequences','引申为获得先前行为带来的好或坏结果。','benefits follow earlier practice.','书面')],M('The farmers reaped the barley by leaving the ripe crop standing in the field all winter.','The farmers reaped the barley by cutting and gathering it before winter.','reap 是收割并收集庄稼，任其留在田里并未收割。','meaning'),[Q(1,'To reap barley is to…','cut and gather the crop','plant it in the spring','store it in a silo without harvesting','Reap in its agricultural sense means harvest a crop.','meaning'),Q(2,'“They reaped the benefits of careful planning” means they…','received good results from earlier planning','cut the plan into four parts','avoided all outcomes','The figurative sense is to obtain consequences or rewards of prior actions.','meaning'),Q(1,'Which phrase is natural?','reap a harvest','reap a question','reap to a realtor','Reap commonly takes a crop, harvest, benefit, or reward as object.','collocation'),Q(2,'A team ignored safety checks and later reaped the consequences. What did it experience?','the results of its earlier choices','a harvest of wheat','a public reading','Reap can describe experiencing consequences caused by earlier action.','context')]);
P('reaper','From reap + agent suffix -er; reap is Old English rīpan “harvest.” A reaper is a person or machine that cuts and gathers grain.',C('reaper.s1','农业','The old reaper cut the wheat and tied it into neat bundles.','这台旧式收割机割下小麦，并将它们扎成整齐的捆。','a mechanical reaper; a person who reaps','名词，指收割谷物的人或机器。','machine harvests grain.','农业'),M('The reaper planted the wheat seed in spring but never cut or gathered the crop.','The reaper cut and gathered the wheat when it ripened.','种植小麦不是收割；reaper 是收割者或收割机。','meaning'),[Q(1,'A mechanical reaper is used to…','cut and gather grain','measure a field’s temperature','rearrange a library','A reaper is a machine for harvesting grain.','meaning'),Q(1,'A reaper may be…','a person or machine that harvests crops','a reader of novels only','the crop itself','The noun names the agent or implement that reaps.','meaning'),Q(1,'Which phrase is natural?','a wheat reaper','a reaper of quarts','reaper the barley in the sense of planting','A wheat reaper harvests wheat.','collocation'),Q(1,'How is reaper formed?','reap + -er','rear + -ship','read + -ly','The suffix -er creates an agent noun from reap.','word-formation')]);
P('reappear','From re- “again” + appear, from Old French aparoir and Latin apparere “come into view”; reappear means appear again after absence.',C('reappear.s1','通用','The sun reappeared after the storm clouds moved east.','暴风云向东移开后，太阳再次出现。','reappear after + absence/event','不及物动词，表示先消失或不在，之后再次出现。','sun returns to view.','通用'),M('The moon reappeared for the first time and had never been visible before.','The moon appeared for the first time and had never been visible before.','“第一次出现”不可能同时表示再次出现。','meaning'),[Q(1,'If a lost dog reappears, it…','appears again after being missing','is seen for the first time ever','becomes a reaper','Reappear means appear another time.','meaning'),Q(1,'Which sentence uses reappear correctly?','The actor reappeared on stage after the break.','The actor reappeared before he had ever appeared.','The actor reappeared the curtain by hand.','Reappear is intransitive and describes returning to view or presence.','grammar'),Q(1,'A rainbow disappears behind clouds, then reappears. It…','comes into view again','is created for the first time','is moved to another realm','The prefix re- indicates its renewed appearance.','context'),Q(1,'What does re- mean in reappear?','again','under','not','The prefix re- means again or back.','word-formation')]);
P('reapply','From re- + apply; apply derives from Latin applicare “attach, put to.” Reapply means submit another application or put a substance on again.',[C('reapply.s1','通用','She plans to reapply for the scholarship after improving her grades.','提高成绩后，她打算再次申请这项奖学金。','reapply for a job/permit','再次递交申请。','new application follows earlier one.','通用'),C('reapply.s1','通用','Reapply sunscreen every two hours when you are outdoors.','在户外时，每两小时重新涂一次防晒霜。','reapply cream/paint/sunscreen','再次把涂层或物质涂到表面。','sunscreen is put on again.','通用')],M('She reapplied sunscreen once in the morning and then insisted that she had put it on again every hour.','She applied sunscreen again every two hours as directed.','只涂一次不是按时重复涂抹；应区分申请义和再次涂抹义。','meaning'),[Q(1,'To reapply for a permit is to…','submit a new application after an earlier one','remove the permit from a wall','apply sunscreen again','Reapply for something means make a fresh application.','meaning'),Q(1,'A label says reapply lotion after swimming. You should…','put the lotion on again','submit a new job application','remove all lotion permanently','Reapply can mean spread a substance on once more.','context'),Q(1,'Which pattern is correct for a job?','reapply for the position','reapply the position to','reapply at the position with','Reapply for is used with a job, scholarship, or permit.','grammar'),Q(1,'The prefix re- in reapply signals…','doing the application or application of a substance again','applying something for the first time','refusing to apply','Re- adds the meaning again.','word-formation')]);
P('rear','The “back” sense is from Old English rear; the verb “raise” is related to Old English ræran. Rear means back part, buttocks, raise/bring up, lift, or located at the back.',[C('rear.s1','通用','The spare tire is stored at the rear of the vehicle.','备用轮胎存放在车辆后部。','at/in the rear of + object','名词：某物的后部或背面。','tire is at back of vehicle.','通用'),C('rear.s2','口语','He slipped and landed on his rear on the muddy path.','他滑了一跤，屁股着地摔在泥路上。','on one’s rear','口语委婉指臀部。','person lands on buttocks.','口语'),C('rear.s3','生活','They rear sheep on the hillside and sell the wool.','他们在山坡上饲养绵羊，并出售羊毛。','rear children/animals','动词：照料、养育儿童或幼小动物直到长大。','farmers raise sheep.','生活'),C('rear.s4','通用','The startled horse reared and lifted both front legs.','受惊的马扬起前身，抬起了两条前腿。','rear up; rear its head','动词：抬起或向后腿站立。','horse rises on hind legs.','通用'),C('rear.s5','通用','The rear entrance stays locked after business hours.','营业时间结束后，后面的入口会锁上。','rear door/entrance','形容词：位于某物后部的。','entrance is at back.','通用')],M('The rear entrance was at the front of the building, beside the main street.','The rear entrance was at the back of the building, away from the main street.','rear 表示后部；正面临街的入口应称 front entrance。','distinction'),[Q(1,'The rear of a bus is…','its back part','its steering wheel','a person who reads','Rear as a noun means the back part of something.','meaning'),Q(2,'He fell on his rear. He landed on his…','buttocks','hands only','a newspaper','Rear can be a mild informal word for the buttocks.','meaning'),Q(3,'To rear a lamb is to…','care for it as it grows','sell its wool before it is born','make it stand on its head','Rear means raise or care for young animals.','context'),Q(4,'A horse rears up when it…','rises on its hind legs','lies down to sleep','runs with all four legs on the ground','Rear as a verb can mean lift the front of an animal’s body.','meaning')]);
P('rearrange','From re- + arrange; arrange comes from French arranger, based on rang “row.” Rearrange means change the positions or order of items.',C('rearrange.s1','通用','We rearranged the chairs so every student could see the screen.','我们重新摆放了椅子，让每位学生都能看见屏幕。','rearrange furniture/items/order','及物动词：再次或以不同方式改变位置、顺序。','new arrangement improves sightlines.','通用'),M('They rearranged the books by leaving every book in precisely the same position and order.','They rearranged the books by sorting them into a new order.','位置和次序完全没变就没有 rearrange。','meaning'),[Q(1,'To rearrange a seating plan is to…','change where people sit','read the plan aloud','reap the seats','Rearrange means organize the positions again.','meaning'),Q(1,'Which phrase is natural?','rearrange the furniture','rearrange to the furniture it','rearrangedly the room','Rearrange takes the objects whose positions are changed.','grammar'),Q(1,'Why might a shop rearrange its shelves?','to put products in a new order or location','to ensure nothing moves','to make the shelves become a realtor','Rearranging changes placement, often to improve access or display.','context'),Q(1,'What does re- add to arrange?','again or in a new way','not','underneath','The prefix signals arranging once more or differently.','word-formation')]);
P('reason','From Old French raison, from Latin rationem “reason, calculation”; reason can be a cause, rational thought, the process of inference, or an attempt to persuade.',[C('reason.s1','通用','The road was closed for the reason that a bridge was unsafe.','道路封闭的原因是桥梁不安全。','the reason for/why/that','名词：解释某事为何发生或做出的事实。','unsafe bridge explains closure.','通用'),C('reason.s2','心理','She used reason rather than anger to settle the disagreement.','她用理性而非愤怒来解决分歧。','use/appeal to reason','名词：清晰、合乎逻辑的思考能力。','logical thought guides resolution.','心理'),C('reason.s3','逻辑','Scientists reasoned from the measurements that the ice was thinning.','科学家根据测量结果推断冰层正在变薄。','reason from + evidence; reason that','动词：通过逻辑推理得出判断。','conclusion follows evidence.','逻辑'),C('reason.s4','通用','I tried to reason with him before he sent the angry email.','在他发出愤怒邮件前，我试着和他讲道理、劝说他。','reason with + person','动词：通过谈话劝某人接受理性判断。','speaker attempts persuasion.','通用')],M('The reason for the closure was that the bridge was perfectly safe and no repairs were needed.','The reason for the closure was that the bridge was unsafe and needed repairs.','桥梁安全且无需维修无法解释道路封闭，因果理由与事实相反。','meaning'),[Q(1,'“The reason for the delay” names…','the cause or explanation of the delay','the person who reads the schedule','the delay’s color','Reason sense 1 is a fact that explains why something happened.','meaning'),Q(2,'Using reason to settle an argument means using…','clear, logical thought','an angry quarrel','a quarterly report','Reason can name the ability to think logically.','meaning'),Q(3,'Scientists reason from evidence when they…','draw a conclusion through logical thinking','ignore the measurements','rearrange the laboratory','Reason as a verb can describe inference from evidence.','context'),Q(4,'To reason with an upset friend is to…','talk in an effort to persuade the friend','make the friend into a reader','write down a reason without speaking','Reason with someone means try to persuade them through discussion.','meaning')]);
P('reasonable','From reason + -able; reason derives from Latin ratio “calculation, rational thought.” Reasonable means fair, sensible, or of a suitable amount.',[C('reasonable.s1','通用','The landlord offered a reasonable rent for an apartment near the station.','房东为车站附近的公寓开出了合理的租金。','reasonable price/request/explanation','形容公平、合乎常理或数量适当。','rent is fair for location.','通用'),C('reasonable.s1','通用','It is reasonable to ask for a written receipt after payment.','付款后索要书面收据是合理的。','it is reasonable to do','表示某行为合情合理、有充分理由。','request is sensible.','通用')],M('A reasonable fee was ten times the usual price and far beyond what anyone could pay.','An unreasonable fee was ten times the usual price and far beyond what anyone could pay.','高出常价十倍且无人负担的费用不合理。','meaning'),[Q(1,'A reasonable price is…','fair and not excessive','impossible to pay by definition','the price of a realtor','Reasonable can describe a fair or suitable amount.','meaning'),Q(1,'Which phrase is natural?','a reasonable explanation','a reasonable of two quarts','reasonably the room up','Reasonable modifies a noun such as explanation, price, or request.','collocation'),Q(1,'If it is reasonable to ask for a receipt, the request is…','sensible and fair','reckless and harmful','a kind of chemical reaction','Reasonable means justified or sensible in the circumstances.','context'),Q(1,'What is the closest opposite of reasonable?','unreasonable','fair','sensible','Unreasonable contrasts with fair and sensible.','distinction')]);
P('reasonably','From reasonable + -ly; reasonable is based on reason. Reasonably means fairly/sensibly or to a moderate, fairly high degree.',[C('reasonably.s1','通用','The committee reasonably asked for a second safety inspection.','委员会合理地要求再进行一次安全检查。','act/reason reasonably','副词：以公平、理智的方式行事。','additional inspection is prudent.','通用'),C('reasonably.s1','通用','The hiking trail is reasonably easy for beginners.','这条徒步路线对初学者来说相当容易。','reasonably + adjective/adverb','也可作程度副词，表示相当、还算，而非极其。','difficulty is moderate.','通用')],M('The committee reasonably ignored all safety evidence and approved the dangerous design.','The committee unreasonably ignored all safety evidence and approved the dangerous design.','无视全部安全证据而批准危险设计不合乎理性。','meaning'),[Q(1,'Someone who responds reasonably…','acts in a fair and sensible way','acts without considering any facts','reappears after an hour','Reasonably sense 1 means in a sensible manner.','meaning'),Q(1,'“The room is reasonably warm” means it is…','fairly or moderately warm','the warmest room in the world','not warm at all','Reasonably can mean to a moderate degree.','meaning'),Q(1,'Which sentence uses reasonably as an adverb?','They reasonably requested more time.','The reasonably of the request was clear.','They were reasonableness the time.','Reasonably modifies requested and describes how they acted.','grammar'),Q(1,'Which is closest to reasonably in “reasonably priced”?','fairly','impossibly','recklessly','Reasonably priced means fairly or moderately priced.','distinction')]);
P('reasoning','From reason + -ing; reason comes via Old French from Latin ratio “calculation.” Reasoning is the process of thinking logically or the argument that results.',C('reasoning.s1','逻辑','Her reasoning linked the rainfall data to the rising river level.','她的推理把降雨数据与河流水位上升联系起来。','line of reasoning; logical reasoning','名词：基于信息进行逻辑思考或形成论证的过程。','evidence is linked to conclusion.','逻辑'),M('His reasoning was sound because he ignored the evidence and reached an unrelated conclusion.','His reasoning was unsound because he ignored the evidence and reached an unrelated conclusion.','忽视证据并推出无关结论不是 sound reasoning。','meaning'),[Q(1,'Reasoning is the process of…','thinking logically about information','reading a book aloud only','putting a meeting off','Reasoning uses thought to reach judgments or conclusions.','meaning'),Q(1,'Which phrase is natural?','a line of reasoning','a reasoning of three quarts','reasoning the lamp out','Line of reasoning is a common expression.','collocation'),Q(1,'A reviewer examines the reasoning behind a conclusion. The reviewer studies…','how the argument moves from evidence to conclusion','only the author’s handwriting','the conclusion’s color','Reasoning concerns the logical steps or argument supporting an outcome.','context'),Q(1,'Which is evidence of weak reasoning?','the conclusion does not follow from the facts','each step is supported by measurements','the argument addresses counterexamples','Sound reasoning connects evidence to a relevant conclusion.','distinction')]);
P('reassurance','From reassure + -ance; reassure comes from re- + assure, from Old French asseurer. Reassurance is speech or action that reduces worry or doubt.',C('reassurance.s1','通用','The doctor’s reassurance helped the patient sleep before the procedure.','医生的安慰让病人在手术前能够入睡。','offer/give reassurance; reassurance that + clause','名词：恢复某人的信心、减轻担忧的话语或行动。','doctor eases patient’s fear.','健康'),M('Her reassurance increased his fear by telling him the treatment was guaranteed to fail.','Her reassurance eased his fear by explaining how the treatment would be monitored.','保证治疗一定失败会加重担忧，不构成安慰或再保证。','meaning'),[Q(1,'Reassurance is intended to…','reduce someone’s doubt or fear','make uncertainty worse','measure a reagent','Reassurance restores confidence or eases worry.','meaning'),Q(1,'Which phrase is natural?','offer reassurance to a patient','reassurance a patient into a room','a reassurance of four inches','One can offer or give reassurance to someone.','collocation'),Q(1,'A manager reassures staff that jobs are safe. The manager…','tries to remove their worry','announces that everyone will be dismissed','asks them to form a queue','Reassurance can be a statement intended to calm concern.','context'),Q(1,'Which is closest to reassurance?','comforting confirmation','rebuke','rebellion','Reassurance provides confidence or comfort.','meaning')]);
P('reassure','From re- + assure, from Old French asseurer “make sure”; reassure means reduce worry or repeat an assurance so people trust it.',[C('reassure.s1','通用','The nurse reassured the child that the injection would be quick.','护士向孩子保证，注射很快就会结束，让他安心。','reassure someone that + clause','使某人减轻担心或疑虑。','nurse comforts child with information.','健康'),C('reassure.s2','正式','The company reassured investors that the delayed payment was secure.','公司再次向投资者保证，延期款项有保障。','reassure someone that + claim','再次作出保证，使听者恢复信任。','company repeats an assurance.','商务')],M('The nurse reassured the child by telling him the injection would hurt forever and there was no help.','The nurse reassured the child by explaining that the brief injection would be over quickly.','永久疼痛且无人帮助会恐吓孩子，不能起到 reassuring 作用。','meaning'),[Q(1,'To reassure a worried child is to…','make the child feel less worried','give the child a chemical reagent','delay the child’s reading','Reassure means reduce worry or doubt.','meaning'),Q(2,'A company reassures investors about a delayed payment by…','repeating that the payment is secure','refusing to communicate','quashing the investors’ receipts','Reassure can mean repeat an assurance to restore trust.','context'),Q(1,'Which construction is correct?','reassure her that the test is routine','reassure her the test to routine','reassure to her about that the test','Reassure someone that + clause is a common pattern.','grammar'),Q(1,'Which verb is closest to reassure?','comfort','alarm','rebuke','Reassure comforts or restores confidence, unlike alarm.','distinction')]);
P('reaumur','Named after French scientist René-Antoine Ferchault de Réaumur, who proposed the scale in 1730; the historical scale sets water freezing at 0° and boiling at 80°.',C('reaumur.s1','科学','The old laboratory notebook recorded the temperature as 20 degrees Réaumur.','旧实验笔记把温度记为列氏20度。','degrees Réaumur; Réaumur scale','历史温标，水的冰点为0度、沸点为80度。','temperature is expressed on historical scale.','科学'),M('On the Réaumur scale, water freezes at 80 degrees and boils at zero.','On the Réaumur scale, water freezes at zero and boils at 80 degrees.','列氏温标的冰点为0度、沸点为80度，错误例颠倒了端点。','measurement'),[Q(1,'On the Réaumur scale, water freezes at…','0 degrees','32 degrees','80 degrees','The historical scale sets freezing at zero.','measurement'),Q(1,'At what Réaumur temperature does water boil?','80 degrees','0 degrees','100 degrees','The scale spans 80 degrees from freezing to boiling.','measurement'),Q(1,'The Réaumur scale is named after…','a French scientist','a real-estate agent','a river in England','The scale takes its name from René-Antoine Ferchault de Réaumur.','context'),Q(1,'Which statement is correct?','Réaumur is a historical temperature scale.','Réaumur is a unit of land area.','Réaumur is a type of reader.','The source entry identifies it as a temperature scale.','meaning')]);
P('rebate','From Middle French rabattre “beat down, reduce,” from re- + abatre “beat down”; a rebate is money returned after a purchase or payment.',C('rebate.s1','商务','The manufacturer offered a rebate of $40 after customers registered the appliance.','消费者登记这台电器后，制造商提供40美元返款。','claim/receive a rebate; rebate on + purchase','名词：满足条件后返还给买方的一部分钱。','refund follows registration.','商务'),M('The rebate increased the final cost because the seller charged the customer an additional fee.','The extra fee increased the final cost; the rebate reduced it by returning part of the payment.','rebate 是返还部分款项、降低净成本，不是额外收费。','meaning'),[Q(1,'A customer receives a rebate after buying a refrigerator. The customer gets…','part of the money paid back','a new refrigerator from a realtor','a higher bill','A rebate is money returned after a purchase.','meaning'),Q(1,'Which phrase is natural?','a rebate on the purchase','a rebate of the queue','rebate the receipt to death','A rebate on a purchase is a standard phrase.','collocation'),Q(1,'Why might a company offer a rebate?','to return some money to qualifying buyers','to make buyers pay more than the listed price','to delay all deliveries','A rebate is a partial refund or reduction in cost.','context'),Q(1,'Which word is closest to rebate in this context?','refund','penalty','reagent','A rebate returns part of the purchase price.','meaning')]);
P('rebel','From Latin rebellare “renew war,” from re- “again” + bellare “wage war”; it can mean a person opposing authority, a nonconformist, or to resist.',[C('rebel.s1','政治','The rebels occupied the bridge and demanded the government resign.','叛乱者占领了桥梁，并要求政府辞职。','rebel against + government/authority','名词：反抗政府或掌权者的人。','group challenges political authority.','政治'),C('rebel.s2','社会','As a teenager, she was a rebel who refused to follow every fashion trend.','十几岁时，她是个叛逆者，不愿追随所有时尚潮流。','a rebel against convention','名词：不遵循常规习俗的人。','person resists social convention.','社会'),C('rebel.s3','政治','Several provinces rebelled against the new ruler.','几个省份反抗了新统治者。','rebel against + authority','动词：反抗、拒绝服从权威。','provinces resist rule.','政治')],M('The rebel supported the ruler’s orders and helped suppress every protest.','The loyal official supported the ruler’s orders; the rebels resisted them.','支持统治者并镇压抗议者是忠诚官员的行为，不是 rebel。','distinction'),[Q(1,'A political rebel is someone who…','fights against a government or authority','writes a newspaper for the government','receives a rebate','Rebel sense 1 is a person opposing those in power.','meaning'),Q(2,'A social rebel may refuse to…','follow conventional customs','read a book','reappear on stage','Sense 2 is a person who resists ordinary conventions.','context'),Q(3,'To rebel against a ruler is to…','resist or fight the ruler’s authority','reassure the ruler','reap the ruler’s crops','The verb means oppose or refuse to obey authority.','meaning'),Q(1,'Which phrase is natural?','rebel against the government','rebel the government against','rebel with a government to','Rebel against names the authority being resisted.','grammar')]);
P('rebellion','From Old French rebellion, from Latin rebellio “renewed war,” from rebellare “wage war again”; rebellion is organized resistance to a ruler or authority.',C('rebellion.s1','政治','The rebellion began after the ruler canceled the region’s elected council.','统治者取消该地区民选议会后，叛乱爆发了。','lead/suppress a rebellion; rebellion against + authority','名词：有组织地反抗政府、统治者或权威。','organized political resistance.','政治'),M('The rebellion was a peaceful vote of support for the ruler, with no opposition or resistance.','The demonstration was a peaceful vote of support for the ruler, not a rebellion.','支持统治者且没有任何反抗不构成 rebellion。','meaning'),[Q(1,'A rebellion is…','an organized attempt to resist a government or ruler','a routine reading exercise','a payment returned after shopping','Rebellion means organized opposition to authority.','meaning'),Q(1,'Which phrase is natural?','a rebellion against the ruler','a rebellion of the water temperature','rebellion to read a book','Rebellion against names the authority being resisted.','collocation'),Q(1,'A rebellion may begin when people…','organize to reject a ruler’s control','agree with every order and ask for more','reapply for a library card','Rebellion involves organized resistance.','context'),Q(1,'Which verb commonly combines with rebellion?','suppress','reassure','reap','A government may suppress or put down a rebellion.','collocation')]);
P('rebellious','From rebellion + -ous; rebellion derives from Latin rebellio “renewed war.” Rebellious describes resistance to rules or authority.',C('rebellious.s1','通用','The rebellious students refused to follow the unfair uniform rule.','这些反叛的学生拒绝遵守不公平的校服规定。','rebellious behavior/attitude','形容不愿服从规定、父母或政府，有时公开反抗。','students defy a rule.','通用'),M('The rebellious group obeyed every order immediately and never challenged authority.','The obedient group followed every order and did not challenge authority.','无条件服从权威与 rebellious（反抗的）相反。','meaning'),[Q(1,'A rebellious teenager may…','challenge rules or authority','obey every instruction without question','calculate a physical quantity','Rebellious describes resistance to authority or rules.','meaning'),Q(1,'Which phrase is natural?','a rebellious attitude','a rebellious of three liters','rebellious the receipt in','Rebellious commonly modifies behavior, attitude, group, or teenager.','collocation'),Q(1,'Why might a character be described as rebellious?','the character openly defies an unjust rule','the character follows every custom','the character repairs a bridge','Defying authority fits the adjective.','context'),Q(1,'Which is closest to the opposite of rebellious?','obedient','defiant','insubordinate','Obedient means willing to follow authority, unlike rebellious.','distinction')]);
P('rebirth','From re- “again” + birth; birth comes from Old English gebyrd. Rebirth means a renewed period of growth or revival after decline.',C('rebirth.s1','文化','The old theater’s restoration sparked a rebirth of cultural life downtown.','老剧院修复后，市中心的文化生活重新兴盛起来。','a rebirth of + activity/place','名词：沉寂或衰退之后重新增长、复兴。','restoration renews cultural activity.','文化'),M('The town’s rebirth meant that its businesses closed permanently and no one returned.','The town’s decline continued as its businesses closed and residents moved away.','商业永久关闭、居民离开是衰退，不是重新复兴。','meaning'),[Q(1,'A rebirth of local music means…','music becomes active and popular again','music disappears for the first time','a musical instrument is put out','Rebirth means renewal after a period of decline or inactivity.','meaning'),Q(1,'Which phrase is natural?','a rebirth of interest in astronomy','a rebirth of three quarts','rebirth the queue in','Rebirth of + activity names a renewed phase.','collocation'),Q(1,'A neighborhood has a rebirth after new shops open and residents return. It…','begins thriving again','is permanently abandoned','has been put to death','The prefix re- signals a renewed period of life or activity.','context'),Q(1,'What does re- mean in rebirth?','again or anew','before','without','Rebirth describes being born or flourishing again.','word-formation')]);
P('rebound','From re- + bound, through French rebondir “bounce back”; rebound means bounce after impact, recover after a fall, or a ball returned in sport.',[C('rebound.s1','通用','The rubber ball rebounded off the wall and rolled under the desk.','橡胶球撞到墙后反弹，滚到了桌子底下。','rebound off/from + surface','动词：碰撞后弹回。','ball changes direction after impact.','通用'),C('rebound.s2','通用','Housing prices rebounded after the temporary decline.','房价在短暂下跌后回升。','rebound from + fall/slump','动词：经历下降后回升、恢复。','prices recover after falling.','通用'),C('rebound.s3','通用','The center caught the rebound after the opponent’s missed shot.','对手投篮未中后，中锋抢到了篮板球。','grab/get a rebound','名词：体育中从篮板或篮筐弹回的球；也指迅速复苏。','basketball player secures loose ball.','体育')],M('Prices rebounded after the decline by continuing to fall to a lower level.','Prices continued to decline instead of rebounding.','rebound 表示下跌后的回升，继续下跌不能称为回升。','meaning'),[Q(1,'A ball rebounds off a wall when it…','bounces back after hitting it','melts into the wall','is read aloud','Rebound as a verb means bounce back from a surface.','meaning'),Q(2,'A market rebounds after a slump when it…','recovers and rises again','falls even further without recovery','becomes a receiver','Rebound from a decline means recover.','meaning'),Q(3,'In basketball, a rebound is…','the ball recovered after a missed shot','a three-month business period','a court’s written order','A rebound is a ball that comes off the rim or backboard after a missed shot.','context'),Q(1,'Which phrase is natural?','rebound from a setback','rebound the setback into','rebound at a receipted','Rebound from names the setback followed by recovery.','grammar')]);
P('rebroadcast','From re- + broadcast; broadcast combines broad + cast. Rebroadcast means transmit a programme or signal again.',C('rebroadcast.s1','媒体','The station will rebroadcast the interview tonight for listeners who missed it.','电台今晚将重播这段访谈，方便错过节目的听众收听。','rebroadcast a programme/interview','及物动词：再次播放或转播已播出的内容。','same interview is transmitted again.','媒体'),M('The station rebroadcast the interview for the first time before it had ever been broadcast.','The station broadcast the interview for the first time, then rebroadcast it later.','rebroadcast 表示再次播放，首次播出时不能称为重播。','meaning'),[Q(1,'To rebroadcast a program is to…','transmit it again after an earlier broadcast','broadcast it only once','remove it from the schedule permanently','Rebroadcast means broadcast again.','meaning'),Q(1,'Which phrase is natural?','rebroadcast the championship match','rebroadcast a receipt for payment','rebroadcast the audience into a realm','A program or event can be rebroadcast.','collocation'),Q(1,'A station schedules a rebroadcast for late-night listeners. What will happen?','an earlier program will air again','a new program will be recorded for the first time','the station will stop transmitting','The noun/action refers to a repeated transmission.','context'),Q(1,'What does re- contribute to rebroadcast?','again','across','not','The prefix re- signals that the broadcast occurs another time.','word-formation')]);
P('rebuff','From French rebuffade, related to rebuff “repel, drive back”; a rebuff is a sharp rejection of an offer or approach, and rebuff can be the act of rejecting.',C('rebuff.s1','通用','Her invitation received a blunt rebuff when he said he would not attend.','他表示不会出席，她的邀请遭到了断然拒绝。','a rebuff to + offer/approach','名词：对提议、邀请或友好接近的冷淡拒绝。','invitation is rejected directly.','通用'),M('The manager rebuffed the proposal by warmly accepting it without objection.','The manager accepted the proposal warmly instead of rebuffing it.','热情接受与断然拒绝意思相反。','distinction'),[Q(1,'A blunt rebuff to an invitation is…','a sharp rejection','a written receipt','a second broadcast','Rebuff as a noun means a cold or abrupt refusal.','meaning'),Q(1,'Which phrase is natural?','a rebuff to the offer','a rebuff of the temperature','rebuff the offer to yesterday','A rebuff to an offer is a standard construction.','collocation'),Q(1,'If a friendly suggestion is rebuffed, the person…','rejects it sharply','accepts it with thanks','repeats it on the radio','Rebuff can mean reject a proposal or friendly approach.','meaning'),Q(1,'Which word contrasts with rebuff?','welcome','reject','snub','Welcome is the opposite of rejecting someone’s approach.','distinction')]);
P('rebuild','From re- + build; build comes from Old English byldan. Rebuild means construct again after damage or restore a weakened system, career, or relationship.',C('rebuild.s1','通用','Residents helped rebuild the library after the flood damaged its walls.','洪水损坏图书馆墙体后，居民们帮忙重建。','rebuild a house/system/relationship','及物动词：重新建造或恢复。','building is reconstructed after damage.','通用'),M('The town rebuilt the bridge by leaving the broken structure exactly as it was.','The town rebuilt the bridge by replacing its damaged supports and deck.','保持损坏结构原样并未重建桥梁。','meaning'),[Q(1,'To rebuild a damaged bridge is to…','construct it again or restore it','read it aloud','delay its opening without repairs','Rebuild means build again after damage or destruction.','meaning'),Q(1,'Which phrase can use rebuild figuratively?','rebuild trust','rebuild a question into a queue','rebuild the weather in a quart','Trust or a career can be rebuilt figuratively.','collocation'),Q(1,'After a company loses customers, it may rebuild its reputation by…','addressing complaints and earning trust again','ignoring every customer','closing permanently','Rebuild can describe restoring an organization’s reputation.','context'),Q(1,'What does re- mean in rebuild?','again','under','without','The prefix marks building another time or anew.','word-formation')]);
P('rebuke','From Old French rebuchier “beat back”; it means a sharp expression of disapproval or to speak sharply to someone who has done wrong.',[C('rebuke.s1','通用','The coach gave the player a stern rebuke for ignoring the safety signal.','球员无视安全信号，教练严厉斥责了他。','a sharp/stern rebuke for + behavior','名词：严厉表达不赞同或责备。','coach disapproves of unsafe act.','通用'),C('rebuke.s2','通用','The supervisor rebuked the clerk for sharing private records.','主管因职员泄露私人记录而斥责了他。','rebuke someone for + action','动词：严厉批评做错事的人。','supervisor directly criticizes clerk.','通用')],M('The supervisor rebuked the clerk by praising the leak and asking for more private records.','The supervisor rebuked the clerk for leaking private records and ordered the practice stopped.','鼓励继续泄露并非斥责，不能作 rebuked 的解释。','meaning'),[Q(1,'A stern rebuke is…','a sharp expression of disapproval','a warm congratulation','a real-estate contract','Rebuke as a noun means a severe reprimand.','meaning'),Q(2,'The manager rebuked an employee for falsifying records. The manager…','scolded the employee for the act','gave the employee a rebate','rebroadcast the records','Rebuke as a verb means criticize sharply.','meaning'),Q(1,'Which phrase is natural?','a rebuke for unsafe behavior','a rebuke of four inches','rebuke the behavior into','A rebuke for an action states what was criticized.','collocation'),Q(2,'A teacher rebukes a student who disrupts class. What is the teacher doing?','speaking sharply to correct the student','offering reassurance that no rules exist','rearranging the desks','The verb describes a sharp verbal correction.','context')]);
P('reburial','From re- “again” + burial; burial derives from bury, Old English byrgan. Reburial is burying human remains again, often in a different grave.',C('reburial.s1','社会','The reburial took place after archaeologists returned the remains to the family cemetery.','考古学家将遗骸送回家族墓地后，重新安葬仪式举行了。','the reburial of remains','名词：遗体或遗骸再次下葬，常因迁移墓地。','remains are buried a second time.','社会'),M('The family called the first burial a reburial even though the remains had never previously been buried.','The family called it a burial because the remains were being laid to rest for the first time.','reburial 要求此前已经安葬过；首次下葬不是“再次安葬”。','word-formation'),[Q(1,'A reburial is…','burying remains for a second time','digging a new quarry','rebroadcasting a service','Reburial means a second burial, often after remains are moved.','meaning'),Q(1,'Why might a reburial occur?','remains are transferred to a family cemetery','a person receives a receipt','a building is rebuilt','Relocation of remains can lead to reburial.','context'),Q(1,'Which phrase is natural?','the reburial of the remains','the reburial of a quart','reburial the body up','Reburial of remains is a natural noun phrase.','collocation'),Q(1,'What does re- mean in reburial?','again','under','far away','The prefix indicates burial another time.','word-formation')]);
P('rebut','From Anglo-French rebouter “push back,” from re- + bouter “thrust”; rebut means argue strongly against a claim or allegation.',C('rebut.s1','通用','The scientist rebutted the accusation with laboratory records and dated samples.','科学家用实验室记录和带日期的样本驳斥了指控。','rebut a claim/argument/allegation','及物动词：用论据反驳某一说法。','evidence directly answers allegation.','通用'),M('The scientist rebutted the claim by repeating it and offering no contrary evidence.','The scientist repeated the claim but did not rebut it; she rebutted it only after presenting contrary evidence.','复述而不提出反面论据并未驳斥该主张。','meaning'),[Q(1,'To rebut an allegation is to…','argue strongly against it','accept it without discussion','repeat it on television','Rebut means refute or argue against a statement.','meaning'),Q(1,'Which phrase is natural?','rebut the evidence','rebut the evidence into a receipt','rebut with a quart of water','One can rebut a claim, argument, or allegation.','collocation'),Q(1,'A lawyer rebuts a witness’s claim by…','presenting evidence that challenges it','agreeing with it silently','changing the courtroom’s color','Rebuttal directly contests a statement with argument or evidence.','context'),Q(1,'Which is closest to rebut?','refute','reassure','reap','Refute is a close synonym for rebut.','meaning')]);
P('recalcitrant','From Latin recalcitrare “kick back,” from re- + calx “heel”; recalcitrant describes stubborn refusal to comply and can name a resistant person.',C('recalcitrant.s1','书面','The recalcitrant tenant refused to follow the court’s repeated safety orders.','这位顽抗的租户拒绝遵守法院多次发布的安全命令。','a recalcitrant person/group; recalcitrant to + authority','形容词或名词，指顽固拒绝服从命令或劝告。','repeated defiance shows resistance.','书面'),M('The recalcitrant witness followed every instruction immediately and never resisted authority.','The compliant witness followed every instruction immediately and never resisted authority.','立即服从而不抵抗与 recalcitrant（顽抗的）相反。','meaning'),[Q(1,'A recalcitrant employee is…','stubbornly unwilling to comply','eager to follow every instruction','a person who receives a package','Recalcitrant means resistant to authority or orders.','meaning'),Q(1,'Which phrase is natural?','a recalcitrant group','a recalcitrant of two quarts','recalcitrant the bridge out','Recalcitrant commonly modifies a person, group, or behavior.','collocation'),Q(1,'A recalcitrant child keeps refusing a reasonable request. The child is…','defiant and resistant','readily cooperative','a qualified reader','Repeated refusal fits recalcitrant.','context'),Q(1,'Which is the closest opposite of recalcitrant?','compliant','obstinate','defiant','Compliant means willing to obey or cooperate.','distinction')]);
P('recall','From re- + call; call comes from Old Norse kalla. Recall means remember, order a person/product back, or the act/ability of remembering.',[C('recall.s1','通用','I can still recall the smell of rain on the warm pavement.','我仍记得雨水落在温热路面上的气味。','recall a memory/name; recall that + clause','动词：把过去的事情重新带回记忆。','speaker remembers a past experience.','通用'),C('recall.s2','商业','The manufacturer recalled the kettle after reports of overheating.','有过热报告后，制造商召回了这款水壶。','recall a product/person','命令产品退回或要求人员返回。','faulty goods are returned.','商业'),C('recall.s3','通用','Her recall of names improved after daily practice.','每天练习后，她记名字的能力有所提高。','have a good/poor recall of + information','名词：记忆某信息的能力，也指召回命令。','ability to remember improves.','通用')],M('I recall the meeting clearly because I have no memory of attending it.','I do not recall the meeting because I have no memory of attending it.','“清楚记得”和“完全没有记忆”互相矛盾。','meaning'),[Q(1,'To recall an earlier conversation is to…','remember it','send it back to a factory','rearrange it in a room','Recall sense 1 means bring a past event back to mind.','meaning'),Q(2,'A company recalls a faulty toaster. It…','asks customers to return it','helps customers remember it','broadcasts it again','Product recall means request return of potentially faulty goods.','context'),Q(3,'A person with excellent recall can…','remember names and details well','rebuild a road quickly','receive a realtor','Recall as a noun can mean the ability to remember.','meaning'),Q(1,'Which phrase is natural?','recall that the door was locked','recall to the door that it locked','recall the locked door into','Recall can take a that-clause to state a remembered fact.','grammar')]);
P('recant','From Latin recantare “take back, unsay,” from re- “back” + cantare “sing”; recant means formally withdraw a belief, statement, or confession.',C('recant.s1','书面','Under pressure, the witness recanted his earlier statement in court.','在压力下，证人在法庭上撤回了先前的陈述。','recant a statement/belief; recant publicly','正式撤回自己先前公开表达的观点、供词或信念。','witness withdraws prior testimony.','法律'),M('The witness recanted his statement by repeating it unchanged and insisting it remained true.','The witness reaffirmed his statement rather than recanting it.','原样重复并坚持观点是重申，不是撤回。','distinction'),[Q(1,'To recant a statement is to…','formally withdraw it','repeat it as true','receive it in the mail','Recant means publicly take back an earlier claim or position.','meaning'),Q(1,'Which phrase is natural?','recant a confession','recant a temperature into a quart','recant the statement by confirming it','One can recant a confession, statement, or belief.','collocation'),Q(1,'A witness recants testimony after admitting it was false. The witness…','withdraws the earlier testimony','makes the testimony more certain','rebroadcasts it','Recanting means withdrawing a previous statement.','context'),Q(1,'Which verb contrasts with recant?','reaffirm','withdraw','retract','Reaffirm means state again as true, opposite to taking it back.','distinction')]);
P('recap','Informal shortening of recapitulate, from Latin recapitulare “go over the main points again”; recap is a brief summary or the act of summarizing.',[C('recap.s1','通用','Before the vote, the chair gave a quick recap of the three options.','表决前，主席简要概述了三个选项。','a quick recap of + topic','名词：简短重述主要内容。','summary reminds listeners.','通用'),C('recap.s2','通用','Could you recap the safety steps for the new volunteers?','你能为新志愿者概述一下安全步骤吗？','recap something for someone','动词：简要概述此前讨论或发生的内容。','speaker is asked to summarize.','通用')],M('The recap omitted every main point and introduced unrelated topics instead.','The recap briefly restated the main points of the discussion.','recap 应简要重述重点，而非遗漏所有重点。','meaning'),[Q(1,'A recap of a meeting is…','a short summary of its main points','the meeting’s receipt','a new meeting held in a quarter','Recap as a noun is a concise summary.','meaning'),Q(2,'To recap the instructions is to…','summarize them briefly','retract them publicly','rebuild the instruction sheet','Recap as a verb means give a summary.','meaning'),Q(1,'Which phrase is natural?','a recap of the discussion','a recap of four quarts','recap to the discussion away','Recap of introduces the subject being summarized.','collocation'),Q(2,'Why might a presenter recap the key results?','to remind the audience of the main points','to prevent anyone from hearing them','to make the results disappear','A recap restates important information briefly.','context')]);
P('recapitulate','From Latin recapitulare, from re- “again” + capitulum “chapter, heading”; recapitulate means restate the main points briefly.',C('recapitulate.s1','书面','At the end, the lecturer recapitulated the evidence for each conclusion.','最后，讲师扼要重述了支持每个结论的证据。','recapitulate the main points','正式动词，简要重述已说过的要点。','summary closes lecture.','书面'),M('The lecturer recapitulated the talk by adding ten unrelated new chapters and never mentioning its main points.','The lecturer recapitulated the talk by briefly restating its main points.','加入许多无关新内容而不重述重点，不是 recapitulate。','meaning'),[Q(1,'To recapitulate an argument is to…','summarize its main points again','begin an unrelated argument','withdraw it from court','Recapitulate means restate the essentials, usually briefly.','meaning'),Q(1,'Which phrase is natural?','recapitulate the findings','recapitulate the color of a wall into','recapitulate at the findings with','The verb takes the points or findings being summarized as its object.','grammar'),Q(1,'A speaker recapitulates the discussion before ending the meeting to…','review the main points for listeners','introduce every topic for the first time','issue a product recall','Recapitulation provides a concise closing review.','context'),Q(1,'Which is the more informal near-synonym of recapitulate?','recap','reburial','rebuff','Recap is a shorter, less formal equivalent.','distinction')]);
P('recapture','From re- + capture, from Latin captura “a taking”; recapture means capture again or bring back a former feeling or quality.',[C('recapture.s1','通用','The guards recaptured the escaped prisoner near the river.','守卫在河边重新抓获了逃犯。','recapture a prisoner/territory','再次抓住此前逃脱或失去的人或物。','escaped person is caught again.','通用'),C('recapture.s1','通用','The old song helped her recapture the excitement of her first trip abroad.','那首老歌让她重温了第一次出国旅行时的兴奋。','recapture a mood/moment/feeling','引申为重新体验或恢复过去的感受。','memory restores past emotion.','通用')],M('The guards recaptured the prisoner for the first time, although he had never escaped or been captured.','The guards captured the prisoner for the first time; they recaptured him after he escaped.','recapture 表示再次抓获；此前若从未抓住或逃脱，就只能称 capture。','word-formation'),[Q(1,'To recapture an escaped prisoner is to…','capture that person again','release the person for the first time','reassure the guards','The prefix re- indicates catching again after an earlier capture.','meaning'),Q(1,'A song can help someone recapture a feeling by…','bringing the feeling back to mind','locking the feeling in a room','making the song a receipt','Recapture can mean experience or recover an earlier mood.','meaning'),Q(1,'Which phrase is natural?','recapture the atmosphere of the festival','recapture the atmosphere to a quart','recapture at the atmosphere with','One can recapture a mood, moment, or atmosphere.','collocation'),Q(1,'A team recaptures a lost lead in a game. It…','regains the lead it had lost','loses the lead for the first time','ends the game before scoring','Recapture can mean regain something previously held.','context')]);
P('recede','From Latin recedere “go back,” from re- “back” + cedere “go”; recede means move away, fade from memory, or move backward at the hairline.',[C('recede.s1','通用','The shoreline receded as the tide moved out.','潮水退去时，海岸线向后退远。','recede from + place','动词：逐渐向后移动或远离观察者。','water moves away from shore.','通用'),C('recede.s2','书面','The details of the dream receded from her memory by lunchtime.','到午饭时，梦里的细节已从她记忆中逐渐模糊。','recede from memory/view','逐渐减弱、变得不清楚。','memory becomes less vivid.','书面'),C('recede.s3','生活','His hairline began to recede in his thirties.','他三十多岁时发际线开始后移。','hairline/forehead recedes','描述头发前缘逐渐向后退。','front hairline moves back.','生活')],M('The floodwaters receded by rising farther up the walls and covering more streets.','The floodwaters receded by falling and moving back from the streets.','水位继续上升并淹没更多街道是上涨，不是退去。','meaning'),[Q(1,'When floodwaters recede, they…','move back or fall away','rise further into town','are rebroadcast','Recede means move back or diminish.','meaning'),Q(2,'A memory recedes from view when it…','becomes less clear or prominent','returns in sharp detail','is put on a shelf','Sense 2 is gradual fading from memory or attention.','meaning'),Q(3,'A receding hairline is…','moving farther back from the forehead','growing forward over the eyes','a recently purchased comb','The hairline is retreating toward the back of the head.','context'),Q(1,'Which preposition commonly follows recede in a spatial sense?','from','of into','between at','Recede from a place means move away from it.','grammar')]);
P('receipt','From Anglo-French receite, from Latin recepta “things received”; a receipt is a written record that payment has been made.',C('receipt.s1','商务','Keep the receipt in case you need to return the headphones.','请保留收据，以备需要退还耳机时使用。','keep/show a receipt; receipt for + purchase','名词：证明商品或服务已付款的凭证。','document records completed payment.','商务'),M('The receipt proved the customer had paid even though it listed no purchase, date, or amount.','The receipt listed the purchase, date, and amount as proof of payment.','缺少交易信息的空白纸条不能可靠证明付款。','meaning'),[Q(1,'A store receipt usually records…','that goods or services were paid for','a person’s reading habits','the depth of a quarry','A receipt is a record of payment.','meaning'),Q(1,'Why keep a receipt after buying headphones?','to show proof of purchase if returning them','to apply sunscreen again','to recapture a song','Receipts can document the transaction for returns or warranty claims.','context'),Q(1,'Which phrase is natural?','a receipt for the purchase','a receipt to four quarts','receipt the payment back','Receipt for identifies the transaction documented.','collocation'),Q(1,'Which word is the correct spelling for a payment record?','receipt','reciept','receitp','Receipt is spelled r-e-c-e-i-p-t.','spelling')]);
P('receipts','From receipt + plural -s; receipt traces to Latin recepta “things received.” Receipts means money received, especially over a period.',C('receipts.s1','金融','The museum’s ticket receipts doubled during the summer exhibition.','夏季展览期间，博物馆的门票收入翻了一倍。','ticket/sales/tax receipts','复数名词：收到的款项或收入，常指某时期的进款。','ticket sales bring in revenue.','金融'),M('The shop’s receipts fell because it received more money from every sale.','The shop’s receipts rose because it received more money from every sale.','收款金额增加应使 receipts 上升，而非下降。','measurement'),[Q(1,'A store’s receipts for the month are…','money it received during that period','paper slips only, regardless of money','the people who bought its products','Receipts in the plural can mean money received.','meaning'),Q(1,'Which phrase is natural?','box-office receipts','box-office receipts are a type of quail','receipt the audience off','Receipts commonly describes revenue from ticket sales.','collocation'),Q(1,'A film has high box-office receipts. It…','earned a large amount from ticket sales','gave every viewer a payment slip only','was never shown in theaters','The phrase refers to money taken in at the box office.','context'),Q(1,'Why is receipts plural in “the receipts increased”?','It refers collectively to incoming payments or revenue.','It means one payment slip only.','It is the past tense of receive.','Plural receipts often denotes a stream or total of funds received.','grammar')]);
P('receive','From Anglo-French receivre, from Latin recipere “take back, accept”; receive means get, experience treatment, welcome a guest, or pick up a signal.',[C('receive.s1','通用','We received your application by email this morning.','我们今天早上通过电子邮件收到了你的申请。','receive a letter/package/message','收到别人寄来或交给自己的东西。','application arrives to recipient.','通用'),C('receive.s2','通用','The patient received excellent care during recovery.','患者康复期间得到了很好的照护。','receive treatment/care/criticism','经历或受到某种对待、教育或伤害。','patient experiences care.','通用'),C('receive.s3','社交','The mayor received the visiting scientists at city hall.','市长在市政厅接待了来访的科学家。','receive a guest/delegation','正式欢迎或接待客人。','host welcomes visitors.','社交'),C('receive.s4','通讯','This antenna receives radio signals from the coast.','这根天线接收来自海岸的无线电信号。','receive a signal/broadcast','接收无线电或电视信号并转为声音、图像。','antenna picks up transmission.','通讯')],M('The office received the application by refusing to accept it or record its arrival.','The office received the application and recorded its arrival.','拒绝接收且不记录到达，不能称为 received。','meaning'),[Q(1,'If an office receives an application, it…','gets the application','sends the applicant away without it','rebroadcasts the application','Receive sense 1 means get something sent or given to you.','meaning'),Q(2,'A patient receives treatment. The patient…','experiences care or medical procedures','welcomes a delegation','gets a radio signal','Receive can mean undergo a particular treatment.','meaning'),Q(3,'A host receives a visiting delegation by…','formally welcoming the visitors','sending them a payment receipt','questioning the radio waves','Receive can mean welcome guests.','context'),Q(4,'An antenna receives a broadcast when it…','picks up the radio or television signal','sends a guest home','accepts a printed receipt','Sense 4 is signal reception by a device.','meaning')]);
P('receiver','From receive + agent suffix -er; receive comes from Latin recipere. Receiver means a person who gets something, a signal device, or a court-appointed administrator for a troubled firm.',[C('receiver.s1','通用','The receiver of the scholarship thanked the donors in a letter.','奖学金获得者写信感谢了捐赠人。','the receiver of + gift/message','名词：收到礼物、款项或信息的人。','person receives award.','通用'),C('receiver.s2','通用','The radio receiver picked up the weather warning clearly.','无线电接收器清晰地收到了天气警报。','radio/telephone receiver','接收无线电、电视或电话信号的设备。','device receives signal.','通讯'),C('receiver.s3','通用','The court appointed a receiver to manage the insolvent company.','法院指定一名接管人管理这家资不抵债的公司。','appoint a receiver','法律/商业义：法院指定管理债务企业财产的人。','administrator manages distressed firm.','通用')],M('The radio receiver sent the broadcast from the station rather than picking it up.','The radio transmitter sent the broadcast, while the receiver picked it up.','发送信号的设备是 transmitter；receiver 接收信号。','confusable'),[Q(1,'The receiver of a gift is…','the person who gets it','the person who wraps it only','the gift itself','Receiver sense 1 names the recipient.','meaning'),Q(2,'A radio receiver is a device that…','picks up broadcast signals','sends the program to the station','writes a court order','A receiver processes incoming signals.','meaning'),Q(3,'A court-appointed receiver may…','manage the assets of an insolvent company','receive a radio signal','give a birthday gift','The legal/business sense is a person placed in control of a troubled firm.','context'),Q(2,'Which device is the opposite of a receiver in signal direction?','transmitter','receptacle','realtor','A transmitter sends signals; a receiver takes them in.','distinction')]);
P('recent','From Latin recentem, present participle of recēns “fresh, new”; recent means happening or beginning a short time ago or belonging to the near past.',[C('recent.s1','通用','A recent storm damaged several homes along the coast.','最近的一场风暴损坏了沿海的几所房屋。','a recent event/change','指刚发生或开始不久的事情。','storm occurred not long ago.','通用'),C('recent.s2','历史','The museum’s recent-history gallery begins with events from the 1990s.','博物馆的近代史展厅从20世纪90年代的事件讲起。','recent history','形容较接近现在的历史时期。','gallery covers near past.','历史')],M('A recent event happened thousands of years in the distant past and has no connection to the present.','A recent event happened not long ago and may still affect the present.','遥远古代事件通常不称 recent。','meaning'),[Q(1,'A recent storm happened…','a short time ago','in the distant geological past','after the next century','Recent means happening or starting not long ago.','meaning'),Q(2,'A recent-history exhibit is about…','a period relatively close to the present','the earliest life on Earth only','a future event','Sense 2 refers to a near-past historical period.','context'),Q(1,'Which phrase is natural?','recent developments','recently a developments','a recent of three quarts','Recent commonly modifies events, news, changes, or developments.','collocation'),Q(1,'Which contrasts with recent?','ancient','newly begun','near in time','Ancient refers to the distant past, opposite to recent.','distinction')]);
P('recently','From recent + -ly; recent comes from Latin recēns “fresh.” Recently means a short time ago or not long before the present.',C('recently.s1','通用','They recently moved into a house near the river.','他们最近搬进了河边的一所房子。','recently + past-tense verb; have recently + past participle','副词，指不久前发生的事情。','move occurred close to now.','通用'),M('She recently moved in 400 years ago and has not lived here since.','She moved in recently and has lived here since.','四百年前属于遥远过去，不可能是 recently。','meaning'),[Q(1,'If a store recently opened, it opened…','not long ago','many centuries in the future','before its building existed','Recently means a short time before now.','meaning'),Q(1,'Which sentence uses recently correctly?','We recently received the package.','We recently receive the package tomorrow.','Recently we will have received it yesterday.','Recently commonly modifies past-tense or present-perfect events.','grammar'),Q(1,'A recently repaired bridge was repaired…','a short time ago','in the distant future','before it was built','The adverb marks an action near the present.','context'),Q(1,'Which is closest in meaning to recently?','not long ago','never','annually','Recently means a short time ago.','meaning')]);
P('receptacle','From Latin receptaculum “a place to receive,” from recipere “receive”; a receptacle is a container or space that receives and holds something.',C('receptacle.s1','通用','Put the used batteries in the marked receptacle by the entrance.','把用过的电池放进入口旁标记的回收容器。','a receptacle for + contents','名词：用于容纳、收集或接收物品的容器或空间。','container receives used batteries.','通用'),M('The receptacle held the batteries by standing empty and having no space for anything.','The receptacle held the batteries inside its compartment.','空着且没有容纳空间的物件不能发挥 receptacle 的功能。','meaning'),[Q(1,'A receptacle is an object or space that…','holds or receives something','sends a broadcast','argues over small details','Receptacle means a container or receiving space.','meaning'),Q(1,'Which phrase is natural?','a receptacle for waste','a receptacle of four feet long in time','receptacle the debate away','A receptacle for waste names its intended contents.','collocation'),Q(1,'A marked receptacle stands by a recycling station. It is for…','collecting items placed inside','measuring the station’s readership','welcoming a visiting delegation','Receptacles hold objects or waste.','context'),Q(1,'Which word is closest in meaning to receptacle?','container','rebuke','recession','A receptacle is a kind of container.','meaning')]);
P('reception','From Latin receptio “a receiving,” from recipere “receive”; reception can mean a front desk, a welcome party, the public response, or signal quality.',[C('reception.s1','生活','Please leave your key at reception when you check out.','退房时请把钥匙留在接待处。','at reception; reception desk','名词：酒店或办公室迎接访客的前台/接待处。','key is left at front desk.','生活'),C('reception.s2','社交','The couple held a reception for their guests after the ceremony.','仪式结束后，这对新人为宾客举办了招待会。','a wedding/official reception','欢迎或庆祝性质的正式聚会。','event welcomes guests.','社交'),C('reception.s3','通用','The proposal received a warm reception from the neighborhood council.','这项提案受到了社区委员会的热烈欢迎。','receive a warm/cool reception','指人群对作品、提案或来访者的反应。','audience responds positively.','通用'),C('reception.s4','通讯','The radio’s reception improved when we moved it near the window.','把收音机移到窗边后，接收效果改善了。','good/poor radio reception','指无线电或电视信号的接收质量。','signal quality improves.','通讯')],M('The radio’s reception was excellent because no signal reached the device at all.','The radio’s reception was poor because no signal reached the device.','没有收到任何信号属于 poor reception，而非 excellent。','meaning'),[Q(1,'At a hotel, reception is…','the desk or area where guests are welcomed','a three-month financial period','a written receipt','Reception sense 1 is the front desk.','meaning'),Q(2,'A wedding reception is…','a party held to welcome and celebrate with guests','the wedding certificate only','a signal from a radio','Sense 2 is a formal social gathering after an event.','meaning'),Q(3,'A proposal receives a warm reception when people…','respond to it favorably','put it to death','fail to hear it on radio','Reception can mean the audience’s response.','context'),Q(4,'Poor radio reception means…','the signal is weak or unclear','the front desk is closed','the proposal was warmly welcomed','Sense 4 concerns how well a device gets a broadcast signal.','meaning')]);
P('receptionist','From reception + -ist; reception derives from Latin receptio “a receiving.” A receptionist greets visitors at a hotel or office desk.',[C('receptionist.s1','通用','The hotel receptionist handed the guests their room keys.','酒店接待员把房间钥匙交给了客人。','hotel receptionist','在酒店迎接住客、办理入住并提供房卡的人。','staff member welcomes hotel guests.','通用'),C('receptionist.s2','通用','The office receptionist answered the phone and directed visitors upstairs.','公司前台接听电话，并引导访客上楼。','office receptionist; receptionist at + organization','办公室接待员负责接听电话和迎接访客。','worker manages calls and visitors.','通用')],M('The receptionist welcomed hotel guests by refusing to greet them or provide their room keys.','The receptionist welcomed hotel guests and gave them their room keys.','拒绝接待和提供房卡不是酒店接待员履行职责的方式。','meaning'),[Q(1,'A hotel receptionist often…','welcomes guests and provides room keys','repairs radio signals','quashes a rebellion','Receptionists greet guests and help with check-in.','meaning'),Q(2,'An office receptionist may…','answer calls and welcome visitors','harvest grain','measure an angular quadrant','The office sense includes answering phones and directing visitors.','context'),Q(1,'Which phrase is natural?','ask the receptionist for directions','ask the receptionist to reap the wheat','receptionist a receipt back','Visitors ask a receptionist for information or help.','collocation'),Q(1,'What is a receptionist’s usual workplace?','a hotel or office front desk','a quarry deep underground','a ship’s engine room only','Receptionists commonly work at reception desks.','meaning')]);
P('receptive','From Latin receptivus, from recipere “receive”; receptive describes willingness to consider ideas or readiness to take in influences.',C('receptive.s1','心理','The committee was receptive to suggestions from first-time applicants.','委员会愿意听取首次申请者提出的建议。','be receptive to + idea/person','形容愿意考虑新想法、建议或影响。','committee listens to proposals.','心理'),M('The receptive audience rejected every idea before listening and refused all new information.','The unreceptive audience rejected every idea before listening and refused new information.','拒绝倾听并排斥所有新信息不是 receptive。','meaning'),[Q(1,'A receptive listener is…','open to considering what others say','unwilling to hear another idea','a person receiving a radio signal only','Receptive sense 1 is willing to consider ideas.','meaning'),Q(1,'Which preposition follows receptive in the common pattern?','to','under from','between at','One is receptive to suggestions, changes, or ideas.','grammar'),Q(1,'A receptive committee invites comments before deciding. It is…','open to new suggestions','already opposed to every suggestion','rearranging its chairs','Receptiveness involves openness to input.','context'),Q(1,'Which is closest to receptive?','open-minded','hostile to ideas','reckless','Open-minded captures willingness to consider new ideas.','distinction')]);
P('receptiveness','From receptive + -ness; receptive comes from Latin recipere “receive.” Receptiveness is openness or ability to take in ideas, learning, signals, or influences.',C('receptiveness.s1','心理','The teacher valued the class’s receptiveness to unfamiliar viewpoints.','老师很看重全班对陌生观点的接纳态度。','receptiveness to + ideas/learning','名词，指愿意接受建议、学习或受到刺激的特质。','students consider new perspectives.','心理'),M('Her receptiveness to feedback showed when she refused to hear any comments.','Her lack of receptiveness to feedback showed when she refused to hear any comments.','拒绝听取反馈体现缺乏 receptiveness，而非具备这种开放性。','meaning'),[Q(1,'Receptiveness to feedback is…','willingness to hear and consider it','a habit of rejecting all comments','a receipt for a book','Receptiveness means openness to suggestions or influence.','meaning'),Q(1,'Which phrase is natural?','receptiveness to learning','receptiveness of three quarts','receptiveness the radio out','The noun commonly takes to before the input accepted.','collocation'),Q(1,'A team with high receptiveness to training is…','ready to learn from the training','unwilling to attend or listen','already a receiver device','The team’s openness makes it more willing to benefit from instruction.','context'),Q(1,'Which word is the abstract noun related to receptive?','receptiveness','receptor','receipt','Receptiveness names the quality of being receptive.','word-formation')]);
P('receptor','From Latin receptor “one who receives,” from recipere “receive”; a receptor is a cell, organ, or molecule that detects a stimulus and triggers a response.',C('receptor.s1','生物','A light receptor in the eye responds when photons reach the retina.','眼中的感光受体在光子到达视网膜时作出反应。','light/hormone receptor; receptor detects + signal','生物学名词：检测光、激素、药物等信号并引发反应的结构。','cell structure detects stimulus.','生物'),M('The receptor detected the hormone by producing no response and failing to bind it.','The receptor detected the hormone by binding it and triggering a cellular response.','未结合信号、也没有反应不符合 receptor 的检测功能。','meaning'),[Q(1,'A cell receptor typically…','detects a signal and helps trigger a response','stores a paper receipt','rebroadcasts a radio program','Receptors detect stimuli in biological systems.','meaning'),Q(1,'A hormone receptor responds to…','a hormone signal','a quarterly report','a stone quarry','Hormones can bind to specific receptors.','context'),Q(1,'Which phrase is natural?','a receptor on the cell surface','a receptor of three quarts','receptor the signal away','Cell-surface receptor is a standard scientific phrase.','collocation'),Q(1,'How is receptor related to receive?','It names a structure that receives or detects a signal.','It means the person who sends a message.','It is a verb meaning to retract a claim.','The word’s root sense is a receiver.','word-formation')]);
P('recess','From Latin recessus “a retreat,” from recedere “go back”; recess can be a pause in legislative/court work or a break between school lessons.',[C('recess.s1','政治','Parliament returned from recess to debate the emergency bill.','议会休会结束后复会，讨论这项紧急法案。','go into/return from recess','名词：议会或法院暂时停止工作的休会期。','legislative work pauses, then resumes.','政治'),C('recess.s2','教育','The children played outdoors during recess after their reading lesson.','阅读课后，孩子们在课间休息时到户外玩耍。','school recess; during recess','学校课程之间的短暂休息。','students take a break between lessons.','教育')],M('The class held recess by continuing the lesson without a break and preventing students from leaving.','The class held recess by pausing the lesson so students could take a break.','不停课且不让学生休息不是课间休息。','meaning'),[Q(1,'Parliament is in recess when…','its work is temporarily paused','it is voting on every bill continuously','it is a school playground','Recess sense 1 refers to a break in legislative or court work.','meaning'),Q(2,'School recess is…','a short break between lessons','a court’s final verdict','a radio signal','Students often play or rest during recess.','meaning'),Q(1,'Which phrase is natural?','return from recess','return recess into','recess of two liters','An assembly may return from recess when work resumes.','collocation'),Q(1,'Which setting best fits recess sense 2?','children playing between classes','judges writing a ruling','a legislature ending its session for a month','School recess is a break between lessons.','context')]);
P('recession','From Latin recessionem, from recedere “go back”; recession means an economic period of weakening activity or a movement backward.',[C('recession.s1','经济','The recession led several factories to reduce production and hiring.','经济衰退导致几家工厂削减产量和招聘。','economic recession; enter/emerge from recession','经济活动减弱的一段时期。','business activity contracts.','经济'),C('recession.s2','书面','The recession of the floodwater exposed stones along the riverbank.','洪水退去后，河岸边的石头显露出来。','the recession of + water/shore','书面义：向后退或退去的动作。','water moves back from bank.','书面')],M('The recession was booming because trade and industry became much more successful.','The economy was booming because trade and industry became much more successful.','贸易和工业增长繁荣与 recession（衰退）相反。','distinction'),[Q(1,'During an economic recession, businesses may…','cut production and hiring','all expand rapidly','receive more quarts of water','A recession is a period of weakened economic activity.','meaning'),Q(2,'The recession of floodwater means the water…','moved back or withdrew','rose to a higher level','was rebroadcast','Recession can also mean a physical movement backward.','meaning'),Q(1,'Which phrase is natural?','a deep recession','a recession of a receptionist','recession the bill back','Deep recession describes a severe economic downturn.','collocation'),Q(1,'If unemployment rises and factories cut output, the economy may be in…','a recession','a rebirth','a reception','Falling activity and rising unemployment are typical recession conditions.','context')]);
P('recessionary','From recession + -ary; recession derives from Latin recedere “go back.” Recessionary means relating to or typical of an economic downturn.',C('recessionary.s1','经济','The recessionary period forced households to postpone large purchases.','经济衰退时期迫使家庭推迟大额消费。','recessionary conditions/period/policy','形容经济衰退期间或具有衰退特征的情况。','weak economy reduces spending.','经济'),M('The recessionary boom featured rapid growth, rising incomes, and record hiring.','The recessionary slump featured falling output, weaker incomes, and reduced hiring.','快速增长和创纪录招聘是繁荣，不符合 recessionary 的衰退特征。','distinction'),[Q(1,'Recessionary conditions are associated with…','economic contraction or weakness','unlimited economic growth','a school break','Recessionary means characteristic of a recession.','meaning'),Q(1,'Which phrase is natural?','recessionary pressure','recessionary of three quarts','pressure recessionary to','Economic pressure can be described as recessionary.','collocation'),Q(1,'A recessionary year may see families…','delay spending because incomes feel uncertain','buy everything without concern','receive a court appointment','Economic weakness can make households cautious.','context'),Q(1,'Which word names the period, rather than describes it?','recession','recessionary','reasonably','Recession is the noun; recessionary is its adjective.','word-formation')]);
P('recessive','From recess + -ive; in genetics it describes a trait or allele that is masked in a hybrid by a dominant version and typically appears when inherited from both parents.',C('recessive.s1','生物','A recessive trait appeared in the child because both parents carried the allele.','由于父母双方都携带该等位基因，孩子表现出了隐性性状。','a recessive gene/trait/allele','遗传学形容词，指在杂合状态下通常不表现的性状或基因。','both parents pass the allele.','生物'),M('A recessive allele was expressed in every hybrid even when a dominant allele was present.','A dominant allele was expressed in the hybrid while the recessive allele was masked.','隐性等位基因在有显性等位基因时通常被掩盖。','distinction'),[Q(1,'A recessive trait is typically expressed when…','the relevant recessive allele is inherited from both parents','a dominant allele always masks it','neither parent passes any allele','A recessive trait commonly appears when two recessive copies are inherited.','meaning'),Q(1,'Which phrase is natural in genetics?','a recessive allele','a recessive receipt','recessive the cell back','Allele is a common noun modified by recessive.','collocation'),Q(1,'A child shows a recessive condition although both parents are unaffected carriers. Why?','the child inherited a recessive allele from each parent','the condition is a radio broadcast','one parent reburied the gene','Two recessive copies can produce the trait.','context'),Q(1,'Which contrasts with recessive?','dominant','masked','inherited','A dominant allele can mask a recessive one.','distinction')]);
P('recharge','From re- + charge; charge comes through Old French charger. Recharge means restore an electrical charge to a battery or regain energy through rest.',[C('recharge.s1','通用','Recharge the camera battery before the long hike.','长途徒步前给相机电池重新充电。','recharge a battery/device','再次把电能储存在电池或设备中。','battery is powered again.','科技'),C('recharge.s1','通用','After a quiet weekend, I felt recharged and ready for work.','安静休息了一个周末后，我恢复了精力，准备好工作。','recharge one’s energy/batteries','引申为通过休息恢复精力。','rest restores energy.','通用')],M('The empty battery recharged by staying unplugged and receiving no electricity.','The empty battery recharged after it was connected to a power source.','未连接电源且没有获得电力，电池不会重新充电。','meaning'),[Q(1,'To recharge a phone is to…','restore electrical power to its battery','remove its battery permanently','rearrange its screen','Recharge a device means charge it again.','meaning'),Q(1,'A quiet day off can help someone recharge by…','restoring energy','making them more tired','giving them a court order','Recharge can figuratively mean regain strength or energy.','context'),Q(1,'Which phrase is natural?','recharge the battery','recharge the battery into a queue','recharge by receipt the screen','Battery is the usual object of the literal verb.','collocation'),Q(1,'Which word part in recharge signals “again”?','re-','-charge','-ge','The prefix re- means again.','word-formation')]);
P('recidivist','From French récidiviste, from Latin recidivus “falling back,” from recidere “fall back”; a recidivist is an offender who commits crimes again after punishment.',C('recidivist.s1','法律','The court treated the recidivist’s repeated burglary convictions as an aggravating factor.','法院将这名惯犯多次入室盗窃定罪视为加重情节。','a convicted recidivist; recidivist offender','名词：受罚后再次犯罪的人。','repeated convictions show relapse.','法律'),M('The first-time offender with no previous conviction was called a recidivist.','The repeat offender with several previous convictions was called a recidivist.','recidivist 指再犯者，初犯且无既往定罪不符合定义。','meaning'),[Q(1,'A recidivist is a person who…','commits crimes again after being punished','receives a scholarship','rebuilds a bridge','Recidivist names a repeat offender.','meaning'),Q(1,'Which phrase is natural?','a recidivist offender','a recidivist of water','recidivist the radio','The noun commonly describes an offender with repeated crimes.','collocation'),Q(1,'A court notes that someone has repeatedly returned to crime after punishment. The person is a…','recidivist','receptionist','realtor','The repeated return to crime fits recidivism.','context'),Q(1,'What does the word’s root idea “falling back” suggest?','relapsing into criminal behavior','reappearing in a theater','receiving a signal','The term refers to returning to offending.','word-formation')]);
P('recipe','From Latin recipe “take,” imperative of recipere; recipes traditionally began with instructions to take ingredients. It means cooking instructions or a method for producing a result.',[C('recipe.s1','饮食','The recipe says to simmer the lentils for twenty minutes.','食谱要求把扁豆慢炖二十分钟。','a recipe for + dish; follow a recipe','名词：制作一道菜所需的材料和步骤。','recipe gives cooking direction.','饮食'),C('recipe.s2','通用','Clear communication is a recipe for a successful project.','清晰沟通是项目成功的诀窍。','a recipe for + result','比喻为产生某种结果的一套方法或条件。','communication contributes to success.','通用')],M('The recipe for soup said to omit every ingredient and never cook anything.','The recipe for soup listed the ingredients and explained how to cook them.','食谱应指导如何制作菜肴，而不是不给材料和步骤。','meaning'),[Q(1,'A recipe for soup provides…','ingredients and cooking instructions','a real-estate contract','a radio frequency only','Recipe sense 1 is a set of directions for preparing food.','meaning'),Q(2,'“A recipe for success” means…','a method or combination likely to produce success','a cooking card for a cake only','a written receipt of payment','Recipe can figuratively mean a way of achieving an outcome.','meaning'),Q(1,'Which phrase is natural?','follow a recipe','follow a recipe into a quarry','recipe the stove off','One follows a recipe when cooking.','collocation'),Q(2,'Regular practice and feedback can be a recipe for improvement. They are…','conditions likely to produce improvement','a list of ingredients for a meal','proof of a product recall','The figurative use describes a method or set of conditions.','context')]);
P('recipient','From Latin recipientem, present participle of recipere “receive”; recipient means a person who receives something, a letter’s addressee, or rarely receptive.',[C('recipient.s1','通用','Each recipient of the grant received a confirmation email.','每位资助金获得者都收到了一封确认邮件。','recipient of + award/help/message','名词：获得钱、奖项、帮助等的人。','person receives grant.','通用'),C('recipient.s2','通用','The recipient’s address was printed clearly on the package.','包裹上清楚地印着收件人的地址。','email/letter recipient','指信件或包裹的接收人。','address identifies addressee.','通用'),C('recipient.s3','通用','The lecture found a recipient audience among students eager to hear unfamiliar ideas.','这场讲座在渴望了解新观点的学生中找到了乐于接受的听众。','a recipient mind/audience (rare)','罕用形容词，表示乐于接受新观点或印象的。','audience is open to new ideas.','通用')],M('The recipient of the award was the person who gave it away and received nothing.','The recipient of the award was the person who received it.','recipient 是接收者，不是赠予者。','distinction'),[Q(1,'The recipient of a prize is…','the person who receives it','the person who designs the trophy','the award itself','Recipient sense 1 names the receiver of a prize or benefit.','meaning'),Q(2,'The recipient on an envelope is…','the person the letter is addressed to','the person who posted it only','the postal worker’s route','Sense 2 is the addressee or receiver of a letter.','meaning'),Q(3,'In the rare adjective sense, a recipient audience is…','open to receiving new ideas','unable to hear a lecture','the organization paying for it','Recipient can rarely mean receptive or willing to receive impressions.','context'),Q(1,'Which phrase is natural?','recipient of the scholarship','recipient to the scholarship of','recipient the letter out','Recipient of identifies the award or message received.','grammar')]);
P('reciprocal','From Latin reciprocus “moving backward and forward,” perhaps from re- “back” + pro- “forward”; reciprocal means mutual, returned in kind, or a mathematical multiplicative inverse.',[C('reciprocal.s1','正式','The two countries signed a reciprocal agreement to share research data.','两国签署了一项相互协议，共享研究数据。','reciprocal relationship/agreement','形容双方彼此给予或感受到同样的行为、关系。','both countries exchange data.','正式'),C('reciprocal.s2','正式','Their support was reciprocal: each helped the other during emergencies.','他们的支持是互惠的：双方在紧急情况下互相帮助。','reciprocal support/benefit','表示作为回报而给予的相应行动。','help is returned by each side.','正式'),C('reciprocal.s3','数学','The reciprocal of 5 is one fifth, because their product is 1.','5的倒数是五分之一，因为二者乘积为1。','the reciprocal of + number','名词：与某数相乘得到1的数（非零数才有倒数）。','5 × 1/5 = 1.','数学')],M('The reciprocal of 5 was 5 because multiplying them gave 25 rather than 1.','The reciprocal of 5 was one fifth because their product is 1.','倒数相乘应得1，5不是5的倒数。','meaning'),[Q(1,'A reciprocal agreement means…','both parties make corresponding commitments','only one party receives benefits','a person receives a letter','Reciprocal sense 1 means mutual or shared by both sides.','meaning'),Q(2,'If help is reciprocal, each person…','returns help to the other','refuses all assistance','measures the amount in quarts','Reciprocal can mean given in return.','meaning'),Q(3,'What is the reciprocal of 4?','one fourth','4','minus 4','A number and its reciprocal multiply to 1.','measurement'),Q(1,'Which phrase can describe a relationship?','reciprocal trust','reciprocal in a quarry only','trust in a receipt','Reciprocal modifies mutual feelings or relations.','collocation')]);
P('reciprocate','From reciprocal + -ate, from Latin reciprocus “moving back and forth”; reciprocate means return a favor, feeling, or action.',C('reciprocate.s1','社交','When the neighbor watered her plants, she reciprocated by collecting his mail.','邻居帮她浇花后，她收他的邮件作为回报。','reciprocate a favor/feeling; reciprocate by + -ing','动词：以相应行动回报他人的行为。','one helpful act is returned with another.','社交'),M('He reciprocated her kindness by refusing every offer of help and giving nothing in return.','He failed to reciprocate her kindness because he gave nothing in return.','拒绝回报且不给予任何回应不构成 reciprocate。','meaning'),[Q(1,'To reciprocate a favor is to…','do something comparable in return','reject the favor and give nothing back','receive a radio signal','Reciprocate means return a favor or action.','meaning'),Q(1,'Which pattern is natural?','reciprocate by helping','reciprocate to helping it','reciprocate at a quart','Reciprocate by + -ing describes the action used to return a favor.','grammar'),Q(1,'Maya thanks her host by inviting the host to dinner. She…','reciprocates the hospitality','rebukes the host','reburies the invitation','She responds with a comparable act of kindness.','context'),Q(1,'Which verb is closest in meaning to reciprocate?','return','ignore','recede','Reciprocate means give or do something in return.','meaning')]);
P('reciprocity','From reciprocal + -ity; reciprocal comes from Latin reciprocus “moving back and forth.” Reciprocity is mutual exchange or a corresponding relation.',[C('reciprocity.s1','通用','The agreement is based on reciprocity: each side shares data and expertise.','这项协议以互惠为基础：双方分享数据和专业知识。','reciprocity between parties; principle of reciprocity','名词：双方互相给予帮助或利益。','benefit flows in both directions.','通用'),C('reciprocity.s2','通用','The study found reciprocity between trust and cooperation: each strengthened the other.','研究发现信任与合作之间存在相互作用：二者彼此加强。','reciprocity between A and B','也可指两个因素互相匹配或影响的状态。','each factor affects the other.','通用')],M('The partnership showed reciprocity because only one side gave help and the other refused to respond.','The partnership lacked reciprocity because only one side gave help and the other refused to respond.','只有单向给予、没有任何回应说明缺乏互惠。','meaning'),[Q(1,'Reciprocity between two organizations means…','they exchange help or benefits with each other','one receives everything while the other gives nothing','they are both in a queue','Reciprocity is mutual exchange.','meaning'),Q(2,'A study finds reciprocity between trust and cooperation. The two factors…','affect or reinforce each other','have no relation','are both types of receipt','The second sense is a corresponding relation in which two things interact.','context'),Q(1,'Which phrase is natural?','the principle of reciprocity','the reciprocity of a quartz','reciprocity by the ruler only','Principle of reciprocity is a standard phrase for mutual exchange.','collocation'),Q(1,'Which is closest to reciprocity?','mutual exchange','rebuke','recession','Reciprocity describes a two-way exchange or relationship.','meaning')]);
P('recital','From recite + -al, via French récit; recital can be a solo music performance, saying a text from memory, or a detailed account.',[C('recital.s1','通用','The pianist gave a recital of Chopin’s nocturnes in the small hall.','钢琴家在小厅举办了一场肖邦夜曲独奏会。','give/attend a piano recital','名词：一位演奏者或歌手举办的音乐演出。','solo musician performs publicly.','音乐'),C('recital.s2','通用','The child’s recital of the poem was clear and confident.','孩子清晰而自信地背诵了这首诗。','a recital of a poem/text','名词：从记忆中朗诵或背诵。','text is spoken aloud from memory.','通用'),C('recital.s3','通用','The report included a detailed recital of events leading to the closure.','报告详细叙述了导致关闭的一系列事件。','a recital of facts/events','名词：详尽叙述或列举事实。','report lays out events in detail.','通用')],M('The piano recital was a written list of events with no music or performance.','The piano recital was a live musical performance by the pianist.','独奏会是音乐演出，不是没有演奏的事件清单。','distinction'),[Q(1,'A piano recital is…','a public performance by a pianist','a legal receiver managing a company','a brief receipt','Recital sense 1 is a solo music performance.','meaning'),Q(2,'A child gives a recital of a poem by…','saying the poem aloud from memory','playing a piano sonata','writing a rebate request','Sense 2 is an oral recitation.','meaning'),Q(3,'A detailed recital of events in a report is…','an account that lists what happened','a concert ticket','an electrical receiver','Recital can mean a full, detailed narrative of facts.','context'),Q(1,'Which phrase is natural for a music event?','attend a violin recital','attend a recessionary violin','recital the violin away','One attends a recital given by a musician.','collocation')]);
P('recite','From Latin recitare “read aloud,” from re- “back” + citare “call”; recite means say a text from memory or list items one by one.',[C('recite.s1','学习','She recited the first verse without looking at the page.','她没有看书页就背诵了第一节。','recite a poem/verse from memory','从记忆中大声说出诗文或文本。','speaker recalls text.','学习'),C('recite.s2','通用','The witness recited the dates of every meeting in order.','证人按顺序逐一列出了每次会议的日期。','recite a list/names/dates','逐项说出一系列信息。','dates are enumerated.','通用')],M('He recited the poem by reading nothing aloud and leaving out every line.','He recited the poem aloud from memory without looking at the page.','既未朗读也未说出内容不构成 recite。','meaning'),[Q(1,'To recite a poem from memory is to…','say it aloud without reading the text','write a receipt for it','rebroadcast the poem','Recite sense 1 means speak a learned text aloud.','meaning'),Q(2,'A witness recites a list of dates by…','stating each date one after another','singing a piano recital','rearranging the calendar','Sense 2 means enumerate items.','context'),Q(1,'Which phrase is natural?','recite a verse','recite a verse into a quarry','recite at a receiver with','Recite takes the text or list as its direct object.','grammar'),Q(1,'Which is closest to recite?','repeat aloud','recede','reclaim','Reciting involves saying or enumerating aloud.','meaning')]);
P('reckless','From Old English receleas “careless,” from reck “care, heed” + -less; reckless means ignoring danger or consequences, or showing no concern for others.',[C('reckless.s1','法律','The driver made a reckless turn across three lanes without checking traffic.','司机没有查看车流就鲁莽地横穿三条车道。','reckless driving/action','形容不考虑风险或行为后果。','dangerous turn ignores obvious risk.','法律'),C('reckless.s2','通用','His reckless comments showed no concern for the people affected by the closure.','他鲁莽的言论显示，他毫不关心受关闭影响的人。','reckless disregard for + people/rights','表示对他人权利、感受或安全满不在乎。','comments dismiss affected people.','通用')],M('The reckless driver carefully checked every mirror, waited for a clear road, and followed all speed limits.','The cautious driver carefully checked every mirror, waited for a clear road, and followed all speed limits.','遵守安全步骤体现谨慎，不是 reckless。','meaning'),[Q(1,'A reckless driver…','takes dangerous actions without considering risk','carefully follows all safety rules','works at a reception desk','Reckless means heedless of danger or consequences.','meaning'),Q(2,'Reckless disregard for another person’s rights means…','showing no concern for those rights','carefully protecting those rights','receiving those rights by mail','Sense 2 stresses lack of concern for other people.','meaning'),Q(1,'Which phrase is natural?','reckless behavior','reckless of a quart','reckless a receipt back','Reckless commonly modifies actions, driving, behavior, or disregard.','collocation'),Q(1,'A person jumps into unknown water from a high cliff. This may be…','reckless','reasonable','receptive','The action ignores a serious risk.','context')]);
P('reckon','From Old English gerecenian “explain, relate, count”; reckon can mean suppose, calculate, regard someone as, or deal with a force/problem.',[C('reckon.s1','口语','I reckon the repairs will cost about two hundred dollars.','我估计维修费用大约是两百美元。','reckon (that) + clause','口语：认为、估计某事如此。','speaker gives an estimate.','口语'),C('reckon.s2','通用','The cashier reckoned the total before applying the rebate.','收银员在扣除返款前计算了总额。','reckon a total/amount','计算或估算数量。','total is calculated.','通用'),C('reckon.s3','通用','She is reckoned one of the best readers in the department.','她被认为是部门里最优秀的读者之一。','be reckoned + noun/adjective','被认为或被看作某种身份/品质。','others regard her as skilled.','通用'),C('reckon.s4','通用','The team had to reckon with a shortage of qualified staff.','团队不得不认真应对合格员工短缺的问题。','reckon with + problem/person','认真考虑、处理或面对一个困难因素。','shortage must be dealt with.','通用')],M('I reckon the train will arrive at noon, but I have no estimate or opinion about its arrival.','I reckon the train will arrive at noon, though the time is only an estimate.','reckon 在此表示估计或认为，不是完全没有判断。','meaning'),[Q(1,'“I reckon we should leave now” means…','I think we should leave now','I have already received a letter','I refuse to make any judgment','Reckon sense 1 is informal for think or suppose.','meaning'),Q(2,'The cashier reckoned the total. The cashier…','calculated it','reassured the customer','rebroadcast it','Reckon can mean calculate an amount.','meaning'),Q(3,'A writer is reckoned a leading expert. The writer is…','considered a leading expert','asked to recite a poem','required to reapply','Be reckoned means be regarded or considered.','context'),Q(4,'To reckon with a shortage is to…','take it seriously and deal with it','pretend it does not exist','calculate its purple color','Reckon with means face or take account of a challenge.','meaning')]);
P('reclaim','From Old French reclamer, from Latin reclamare “call back, appeal against”; reclaim means get something back, make land usable, or process waste for reuse.',[C('reclaim.s1','通用','She reclaimed her lost suitcase from the airport desk.','她从机场服务台领回了丢失的行李箱。','reclaim something from + place/person','取回丢失、遗留或被占有的东西。','owner gets suitcase back.','通用'),C('reclaim.s2','通用','The city plans to reclaim marshland for a new wildlife park.','市政府计划开垦沼泽地，建设新的野生动物园。','reclaim land from + sea/desert/wetland','通过排水、填海等方式使土地可供耕作或建设。','land is converted for use.','通用'),C('reclaim.s3','通用','The plant reclaims plastic from discarded bottles and makes new containers.','工厂从废弃瓶子中回收塑料，再制成新容器。','reclaim/recycle materials from waste','处理废料，使材料能够再次利用。','plastic is recovered and reused.','通用')],M('The factory reclaimed plastic by throwing it into a landfill where it could never be reused.','The factory reclaimed plastic by sorting, processing, and reusing it.','填埋且不再利用是弃置，不是回收再利用。','meaning'),[Q(1,'To reclaim a lost suitcase is to…','get it back from the place holding it','buy a different suitcase','send it to a quarry','Reclaim sense 1 means recover something lost or left behind.','meaning'),Q(2,'A city reclaims marshland when it…','makes the area usable for building or farming','reburies a suitcase','rebroadcasts the wetland','Land reclamation changes land so it can be used.','context'),Q(3,'A recycling plant reclaims plastic by…','processing waste so the material can be used again','burying every bottle permanently','sending plastic to a realtor','Reclaim in recycling means recover and reuse material.','meaning'),Q(1,'Which construction is natural?','reclaim land from the sea','reclaim the sea to land with','reclaim at plastic by','Reclaim land from the sea is a standard construction.','grammar')]);
})();
